/* ============================================================
   CONTENT GLOSSARY — clickable in-vault dictionary of terms.
   Consumed by window.CONTENT_GLOSSARY; the in-page engine
   underlines every matching term in the Content Vault and pops
   its definition on click. Definitions are textbook-standard.
   ============================================================ */
window.CONTENT_GLOSSARY = [
/* ---------- CLASSICAL MECHANICS ---------- */
{t:"Lagrangian", f:["Lagrangian","Lagrangians"], d:"A function L = T − V (kinetic minus potential energy) of the generalised coordinates, velocities and time. The entire classical dynamics follows from the action S = ∫L dt being stationary (Hamilton's principle), which yields the Euler–Lagrange equations."},
{t:"Hamiltonian", f:["Hamiltonian","Hamiltonians"], d:"A function H(q,p,t) obtained from the Lagrangian by a Legendre transform, H = Σ p q̇ − L. For conservative systems it equals the total energy T + V, and Hamilton's equations q̇ = ∂H/∂p, ṗ = −∂H/∂q give the equations of motion in phase space."},
{t:"generalised coordinate", f:["generalised coordinate","generalised coordinates","generalized coordinate","generalized coordinates"], d:"Any independent coordinate qᵢ that completely specifies the configuration of a system subject to its constraints. They need not be lengths — angles, charge, etc. all qualify; there is one per degree of freedom."},
{t:"generalised momentum", f:["generalised momentum","generalized momentum","canonical momentum"], d:"The conjugate momentum pᵢ = ∂L/∂q̇ᵢ associated with a generalised coordinate. It equals ordinary momentum only when the coordinate is a Cartesian position; it is the variable conjugate to qᵢ in Hamiltonian mechanics."},
{t:"constraint", f:["constraint","constraints"], d:"A restriction that limits the possible positions or velocities of a system. Holonomic constraints can be written f(q,t)=0 (e.g. a particle on a wire) and reduce the degrees of freedom; non-holonomic constraints involve velocities and cannot be integrated to a position relation."},
{t:"degree of freedom", f:["degree of freedom","degrees of freedom"], d:"The number of independent coordinates needed to specify the configuration of a system. Each independent quadratic term (kinetic or potential) also contributes ½kT to the average energy in equipartition."},
{t:"action", f:["action"], d:"The functional S = ∫ L dt evaluated along a path. Hamilton's principle of least action states that the physical path is the one that makes S stationary, δS = 0, which reproduces the equations of motion."},
{t:"Euler–Lagrange equation", f:["Euler-Lagrange equation","Euler–Lagrange equation","Euler–Lagrange equations","Euler-Lagrange equations"], d:"The equation d/dt(∂L/∂q̇ᵢ) − ∂L/∂qᵢ = 0 obtained from δS = 0 for each generalised coordinate. It is the central equation of Lagrangian mechanics and reduces to Newton's second law for Cartesian coordinates."},
{t:"Hamilton's principle", f:["Hamilton's principle"], d:"The variational statement that the true trajectory between two fixed points is the one that extremises the action S = ∫ L dt. It is the foundation of Lagrangian and Hamiltonian dynamics and of the path-integral formulation of quantum mechanics."},
{t:"phase space", f:["phase space"], d:"The 2n-dimensional space whose axes are the generalised coordinates qᵢ and momenta pᵢ. A state is a point, and the trajectory of a system is a curve in phase space; Liouville's theorem states the flow preserves phase-space volume."},
{t:"Liouville's theorem", f:["Liouville's theorem","Liouville theorem"], d:"The theorem that the density of representative points in phase space is constant along trajectories (dρ/dt = 0). Equivalently, Hamiltonian flow preserves phase-space volume — the foundation of classical statistical mechanics."},
{t:"canonical transformation", f:["canonical transformation","canonical transformations"], d:"A change of variables (q,p) → (Q,P) that preserves the Hamiltonian structure of the equations of motion, i.e. the fundamental Poisson brackets {Qᵢ,Pⱼ} = δᵢⱼ. They are generated by generating functions and are the classical analogue of unitary transformations."},
{t:"generating function", f:["generating function","generating functions"], d:"A function F(q,Q), F₁(q,Q) etc. that defines a canonical transformation through derivative relations such as p = ∂F/∂q, P = −∂F/∂Q. It is the classical counterpart of the unitary operator in quantum mechanics."},
{t:"Poisson bracket", f:["Poisson bracket","Poisson brackets"], d:"The bilinear operation {A,B} = Σ (∂A/∂qᵢ ∂B/∂pᵢ − ∂A/∂pᵢ ∂B/∂qᵢ). It gives the time evolution of any observable dA/dt = {A,H} + ∂A/∂t, and {qᵢ,pⱼ} = δᵢⱼ; its quantum analogue is the commutator divided by iħ."},
{t:"cyclic coordinate", f:["cyclic coordinate","cyclic coordinates","ignorable coordinate"], d:"A coordinate that does not appear explicitly in the Lagrangian. Its conjugate momentum is conserved (d/dt ∂L/∂q̇ = 0), a direct consequence of Noether's theorem applied to the corresponding symmetry."},
{t:"Noether's theorem", f:["Noether's theorem","Noether theorem"], d:"The theorem that every continuous symmetry of a system's action corresponds to a conserved quantity: time translation → energy, space translation → momentum, rotation → angular momentum, and gauge symmetry → charge."},
{t:"moment of inertia", f:["moment of inertia","moments of inertia"], d:"The rotational analogue of mass: I = Σ mᵢ rᵢ² about a given axis. It enters L = Iω and the torque equation τ = Iα, and is generalised to the inertia tensor for arbitrary axes."},
{t:"inertia tensor", f:["inertia tensor"], d:"The symmetric 3×3 matrix Iᵢⱼ = ∫ ρ(δᵢⱼ r² − xᵢ xⱼ) dV that encodes the rotational inertia of a rigid body about every axis through a point. Its eigenvectors define the principal axes and its eigenvalues the principal moments."},
{t:"principal axes", f:["principal axes","principal axis"], d:"The three mutually perpendicular axes along which the inertia tensor is diagonal. Rotation about a principal axis has angular momentum parallel to angular velocity, so no torque is needed to keep the axis fixed."},
{t:"Euler's equations", f:["Euler's equations","Euler equations"], d:"The rigid-body equations of motion in the body frame: N₁ = I₁ω̇₁ − (I₂ − I₃)ω₂ω₃ (cyclically), describing torque-free and forced rotation about principal axes. They underlie the precession and nutation of tops."},
{t:"Euler angles", f:["Euler angles","Euler angle"], d:"Three angles (φ, θ, ψ) — precession, nutation and spin — that specify the orientation of a rigid body relative to a fixed frame. In the Z–X–Z convention the rotation matrix is R = R_z(φ)R_x(θ)R_z(ψ)."},
{t:"precession", f:["precession","precesses","precessing"], d:"The slow rotation of a spinning body's axis about an external axis, e.g. a gyroscope's axis tracing a cone about the vertical under gravity, or the Larmor precession of a magnetic moment in a magnetic field."},
{t:"nutation", f:["nutation"], d:"The periodic nodding or wobbling motion of a spinning body's axis (the oscillation of the angle θ between the body axis and the precession axis). Together with precession and spin it completes the Euler-angle description."},
{t:"centre of mass", f:["centre of mass","center of mass"], d:"The point R = Σ mᵢ rᵢ / Σ mᵢ that moves as if all mass were concentrated there and all external forces applied there. The two-body problem reduces to free motion of the centre of mass plus relative motion with the reduced mass."},
{t:"reduced mass", f:["reduced mass"], d:"The effective mass μ = m₁m₂/(m₁+m₂) of the relative motion in a two-body problem. The relative coordinate behaves as a single particle of mass μ moving in the same potential, centred on the force centre."},
{t:"central force", f:["central force","central forces"], d:"A force directed along the line joining a particle to a fixed centre, depending only on distance. It conserves angular momentum, so motion is planar, and reduces to a one-dimensional problem in the effective potential."},
{t:"effective potential", f:["effective potential"], d:"V_eff(r) = V(r) + L²/(2mr²) for radial motion in a central field. The centrifugal term L²/(2mr²) acts as a repulsive barrier; circular orbits occur at its minima and stability is set by its curvature."},
{t:"Kepler's laws", f:["Kepler's laws","Kepler's law","Kepler law"], d:"Three laws of planetary motion: (1) orbits are ellipses with the Sun at a focus; (2) the radius vector sweeps equal areas in equal times (conservation of angular momentum); (3) T² ∝ a³, the square of the period scales as the cube of the semi-major axis."},
{t:"virial theorem", f:["virial theorem"], d:"For bound systems in equilibrium, 2⟨T⟩ = −⟨r·∇V⟩. For a power-law potential V ∝ rⁿ it gives 2⟨T⟩ = n⟨V⟩; for gravity or the Coulomb force (n = −1), 2⟨T⟩ = −⟨V⟩, so E = −⟨T⟩."},
{t:"scattering cross-section", f:["scattering cross-section","cross-section","cross section","cross sections"], d:"A measure of the probability of a scattering event, with units of area. The differential cross-section dσ/dΩ is the scattered flux per unit solid angle per unit incident flux; its integral is the total cross-section."},
{t:"impact parameter", f:["impact parameter"], d:"The perpendicular distance between the projectile's initial trajectory and the scattering centre. Scattering angle is a decreasing function of impact parameter; b = 0 gives head-on (maximum-angle) scattering."},
{t:"Coriolis force", f:["Coriolis force"], d:"The fictitious force −2m(Ω × v) experienced by a body moving with velocity v in a frame rotating with angular velocity Ω. It deflects moving objects (rightward in the northern hemisphere) and drives cyclones and the Foucault pendulum."},
{t:"centrifugal force", f:["centrifugal force"], d:"The fictitious outward force mΩ²r felt in a rotating frame. It is the frame-acceleration term −m(Ω × (Ω × r)) and appears, together with the Coriolis force, when Newton's laws are written in a non-inertial frame."},
{t:"Foucault pendulum", f:["Foucault pendulum"], d:"A long pendulum whose plane of swing slowly rotates with period 24h/sin λ at latitude λ, direct evidence of Earth's rotation. The precession of the swing plane is a Coriolis-effect phenomenon."},
{t:"normal mode", f:["normal mode","normal modes"], d:"A collective oscillation pattern in which all parts of a coupled system move sinusoidally with the same frequency. Any small oscillation is a superposition of normal modes; there are as many modes as degrees of freedom."},
{t:"small oscillation", f:["small oscillation","small oscillations"], d:"Motion near a stable equilibrium, obtained by expanding the potential to quadratic order. The system behaves as coupled harmonic oscillators whose frequencies are the normal-mode frequencies."},
{t:"Lorentz transformation", f:["Lorentz transformation","Lorentz transformations"], d:"The linear coordinate transformation between inertial frames in special relativity: x' = γ(x − vt), t' = γ(t − vx/c²). It leaves the spacetime interval ds² = c²dt² − dx² − dy² − dz² invariant and reduces to the Galilean transformation when v ≪ c."},
{t:"Lorentz factor", f:["Lorentz factor"], d:"The factor γ = 1/√(1 − v²/c²) that appears throughout special relativity. It governs time dilation (Δt = γΔτ), length contraction (L = L₀/γ) and relativistic momentum (p = γmv); γ → ∞ as v → c."},
{t:"time dilation", f:["time dilation"], d:"The relativistic effect that a moving clock runs slow: Δt = γΔτ, where Δτ is the proper time measured in the clock's rest frame. It is verified by muon lifetime and atomic-clock experiments."},
{t:"length contraction", f:["length contraction"], d:"The relativistic shortening of an object along its direction of motion: L = L₀/γ, where L₀ is its rest length. Only the parallel dimension contracts; transverse dimensions are unchanged."},
{t:"four-vector", f:["four-vector","four-vectors","4-vector","4-vectors"], d:"A four-component quantity that transforms under Lorentz transformations, e.g. the spacetime position x^μ = (ct, x), four-momentum p^μ = (E/c, p), and four-current. Invariants are built from the scalar product with the Minkowski metric."},
{t:"Minkowski space", f:["Minkowski space"], d:"The four-dimensional spacetime of special relativity with metric signature (+,−,−,−), where the invariant interval is ds² = c²dt² − dx² − dy² − dz². Events separated by light-like, time-like or space-like intervals are classified by this metric."},
{t:"proper time", f:["proper time"], d:"The time interval measured by a clock moving with the particle, dτ = ds/c. It is a Lorentz invariant, and all observers agree on it; coordinate time dilates relative to it."},
{t:"rest energy", f:["rest energy","rest mass energy"], d:"The energy of a particle at rest, E₀ = mc², from Einstein's mass–energy equivalence. Total energy is E = γmc², and kinetic energy is (γ − 1)mc²."},

/* ---------- ELECTROMAGNETIC THEORY ---------- */
{t:"electric field", f:["electric field"], d:"The force per unit charge E = F/q at a point. Its lines begin on positive charge and end on negative charge; with the potential it fully specifies electrostatics via E = −∇V."},
{t:"electric potential", f:["electric potential","scalar potential"], d:"The work per unit charge to bring a test charge from infinity to a point, V(r) = ∫ E·dl. It is a scalar field whose gradient gives the field E = −∇V; its unit is the volt."},
{t:"Gauss's law", f:["Gauss's law","Gauss law"], d:"The statement that the electric flux through any closed surface equals the enclosed charge over ε₀: ∮E·dA = Q_enc/ε₀ (equivalently ∇·E = ρ/ε₀). It is one of Maxwell's equations and is most useful in symmetric geometries."},
{t:"Coulomb's law", f:["Coulomb's law","Coulomb law"], d:"The force between two point charges: F = q₁q₂/(4πε₀r²) r̂, inverse-square in separation. It is the starting point of electrostatics; the 1/r² form is tied to the photon being massless."},
{t:"charge density", f:["charge density","surface charge density","linear charge density"], d:"Charge per unit volume (ρ), area (σ) or length (λ). The total charge is its integral; Gauss's law relates the divergence of E to ρ."},
{t:"dipole moment", f:["dipole moment","electric dipole moment"], d:"The vector p = Σ qᵢrᵢ (or ∫ρr dV) characterising the separation of equal and opposite charge. Its far field falls as 1/r³ and its potential as 1/r², the leading term when total charge is zero."},
{t:"multipole expansion", f:["multipole expansion","multipoles"], d:"The expansion of the potential of a localised charge distribution in inverse powers of distance: monopole (∝1/r), dipole (∝1/r²), quadrupole (∝1/r³), and so on. Each term is associated with a moment of the charge distribution."},
{t:"quadrupole", f:["quadrupole","quadrupole moment"], d:"The second moment of a charge or mass distribution, describing its departure from spherical symmetry. Its potential falls as 1/r³ and it radiates only when the charge distribution changes with time."},
{t:"polarization", f:["polarization","polarisation","electric polarization"], d:"Two related meanings: (1) in dielectrics, the dipole moment per unit volume P, with bound charges ρ_b = −∇·P and P = ε₀χₑE; (2) for light, the direction of the oscillating electric field, described by linear, circular or elliptical states and by Jones vectors."},
{t:"dielectric", f:["dielectric","dielectrics"], d:"An insulating material that polarises in an electric field, reducing the field inside by a factor of the relative permittivity ε_r. Its molecules develop induced or aligned dipole moments."},
{t:"permittivity", f:["permittivity","dielectric constant"], d:"The measure ε = ε₀ε_r of how a medium transmits electric fields; ε_r is the relative permittivity (dielectric constant). The displacement field is D = εE, and capacitance scales with ε."},
{t:"displacement field", f:["displacement field","electric displacement"], d:"The auxiliary field D = ε₀E + P, whose divergence is the free charge density ∇·D = ρ_f. It simplifies problems with dielectrics because bound charge is absorbed into P."},
{t:"boundary conditions", f:["boundary condition","boundary conditions"], d:"The continuity relations across an interface: E_parallel and D_perp are continuous in electrostatics (with jumps set by free surface charge), while B_perp and H_parallel are continuous in magnetostatics. They fix the fields at material interfaces."},
{t:"Poisson's equation", f:["Poisson's equation","Poisson equation"], d:"∇²V = −ρ/ε₀, the differential form of Gauss's law in terms of the potential. With zero charge it reduces to Laplace's equation ∇²V = 0; its solution with boundary conditions gives the potential everywhere."},
{t:"Laplace's equation", f:["Laplace's equation","Laplace equation"], d:"∇²V = 0, satisfied by the potential in charge-free regions. Its solutions are harmonic functions with no local maxima or minima (so a static E field has no stable equilibrium for a point charge — Earnshaw's theorem)."},
{t:"uniqueness theorem", f:["uniqueness theorem","uniqueness theorems"], d:"The theorem that a solution of Poisson's/Laplace's equation satisfying given boundary conditions (Dirichlet or Neumann) is unique. It justifies solving boundary-value problems by any convenient method, such as images or separation of variables."},
{t:"method of images", f:["method of images","image charge"], d:"A technique that replaces a conductor by fictitious image charges placed so the boundary condition (constant potential) is satisfied. The field in the physical region is then that of the real plus image charges."},
{t:"capacitance", f:["capacitance"], d:"The ratio C = Q/V of stored charge to potential difference, measured in farads. It depends only on geometry and dielectric (e.g. ε₀A/d for a parallel plate); stored energy is ½CV²."},
{t:"Biot–Savart law", f:["Biot-Savart law","Biot–Savart law","Biot Savart law"], d:"The law giving the magnetic field of a steady current element: dB = (μ₀/4π) I dl × r̂/r². Integrated, it yields the fields of wires, loops and solenoids; it is the magnetostatic analogue of Coulomb's law."},
{t:"Ampère's law", f:["Ampère's law","Ampere's law","Ampere law"], d:"∮B·dl = μ₀ I_enc (∇×B = μ₀J) — the circulation of B around a loop equals μ₀ times the enclosed current. Maxwell added the displacement-current term ε₀μ₀ dΦ_E/dt to make it consistent with charge conservation."},
{t:"magnetic flux", f:["magnetic flux"], d:"The flux Φ_B = ∫ B·dA of the magnetic field through a surface, measured in webers. Faraday's law states that a changing flux induces an emf E = −dΦ_B/dt."},
{t:"vector potential", f:["vector potential"], d:"The field A with B = ∇×A, introduced because ∇·B = 0. It is defined only up to a gauge transformation A → A + ∇χ, and appears in the Hamiltonian (p − qA) of a charged particle."},
{t:"magnetic dipole moment", f:["magnetic dipole moment","magnetic moment"], d:"The vector m = I·Area n̂ of a current loop (or m = ½∫r×J dV generally). In a field B it experiences a torque m × B and potential energy −m·B; its far field falls as 1/r³."},
{t:"magnetization", f:["magnetization","magnetisation"], d:"The magnetic dipole moment per unit volume M of a material. Bound currents arise as J_b = ∇×M and K_b = M × n̂; the auxiliary field is H = B/μ₀ − M."},
{t:"permeability", f:["permeability"], d:"The measure μ = μ₀μ_r of a medium's response to magnetic fields; B = μH. Diamagnets have μ_r slightly below 1, paramagnets slightly above, and ferromagnets have μ_r up to ~10⁵."},
{t:"inductance", f:["inductance","self inductance","mutual inductance"], d:"The proportionality between magnetic flux linkage and current: self-inductance L (Φ = LI) and mutual inductance M (Φ₁₂ = MI₂), in henries. The induced emf is E = −L dI/dt; stored magnetic energy is ½LI²."},
{t:"Faraday's law", f:["Faraday's law","Faraday law"], d:"The law that a changing magnetic flux induces an electromotive force: E = −dΦ_B/dt (∇×E = −∂B/∂t). The minus sign is Lenz's law; it is the basis of generators, transformers and induction."},
{t:"Lenz's law", f:["Lenz's law","Lenz law"], d:"The rule that an induced current flows so as to oppose the change in flux that produced it — the minus sign in Faraday's law. It is a consequence of energy conservation."},
{t:"motional emf", f:["motional emf"], d:"The emf E = ∫(v × B)·dl induced in a conductor moving through a magnetic field. It arises from the magnetic force on the charge carriers and equals the rate of change of flux cut by the circuit."},
{t:"displacement current", f:["displacement current"], d:"The term ε₀ dΦ_E/dt (density ε₀∂E/∂t) that Maxwell added to Ampère's law. It acts like a current between capacitor plates and is the source of magnetic field in electromagnetic waves."},
{t:"Maxwell's equations", f:["Maxwell's equations","Maxwell equations"], d:"The four equations of electromagnetism: ∇·E = ρ/ε₀, ∇·B = 0, ∇×E = −∂B/∂t, ∇×B = μ₀J + μ₀ε₀∂E/∂t. Together with the Lorentz force they describe all classical electromagnetic phenomena, including light as a wave."},
{t:"Poynting vector", f:["Poynting vector","Poynting theorem"], d:"S = E × H, the energy flux (power per unit area) carried by the electromagnetic field. Poynting's theorem states ∇·S + ∂u/∂t = −J·E, expressing local energy conservation."},
{t:"plane wave", f:["plane wave","plane waves"], d:"A wave whose surfaces of constant phase are parallel planes, E = E₀ e^{i(k·r − ωt)}. In vacuum E, B and k are mutually perpendicular with E = cB, and the wave travels at c = 1/√(μ₀ε₀)."},
{t:"skin depth", f:["skin depth"], d:"The distance δ = √(2/(μσω)) over which an electromagnetic field decays by e⁻¹ inside a conductor. High-frequency currents flow only in a thin surface layer — the skin effect."},
{t:"waveguide", f:["waveguide","waveguides"], d:"A hollow or dielectric structure that guides electromagnetic waves along its axis. Modes TE_mn/TM_mn propagate only above their cutoff frequency f_c = (c/2)√((m/a)² + (n/b)²)."},
{t:"transmission line", f:["transmission line","transmission lines"], d:"A pair of conductors guiding TEM waves, described by distributed inductance and capacitance (telegraph equations). Its characteristic impedance is Z₀ = √(L/C); mismatches cause reflections and standing waves."},
{t:"characteristic impedance", f:["characteristic impedance"], d:"The ratio of voltage to current in a wave travelling on a transmission line, Z₀ = √(L/C) per unit length. Reflection is absent only when the line is terminated by a load equal to Z₀."},
{t:"Fresnel equations", f:["Fresnel equations","Fresnel's equations"], d:"The equations giving the reflected and transmitted amplitudes of light at a dielectric interface, from matching boundary conditions. They predict Brewster's angle, phase changes and total internal reflection."},
{t:"Brewster angle", f:["Brewster's angle","Brewster angle"], d:"The incidence angle θ_B = arctan(n₂/n₁) at which p-polarised light is not reflected. Reflected light is then completely s-polarised — the basis of polarising (Brewster) windows."},
{t:"total internal reflection", f:["total internal reflection"], d:"Complete reflection of light at an interface when it travels from a denser to a rarer medium beyond the critical angle θ_c = arcsin(n₂/n₁). An evanescent wave still penetrates the second medium."},
{t:"evanescent wave", f:["evanescent wave"], d:"The exponentially decaying wave that exists in the second medium during total internal reflection or below a waveguide cutoff. It carries no net energy across the boundary but enables tunnelling and near-field effects."},
{t:"interference", f:["interference"], d:"The superposition of two or more coherent waves, producing a pattern of maxima and minima where the waves add in phase or out of phase. Young's double slit and thin films are classic examples."},
{t:"diffraction", f:["diffraction"], d:"The bending and spreading of waves around obstacles and apertures, described by Huygens' principle. Fraunhofer (far-field) and Fresnel (near-field) diffraction describe the two limiting regimes."},
{t:"coherence", f:["coherence","coherent"], d:"The property of waves having a stable, well-defined phase relationship. Temporal coherence is set by the coherence time/length (linewidth), spatial coherence by the source size; interference requires coherence."},
{t:"Fabry–Pérot", f:["Fabry-Perot","Fabry–Pérot","Fabry Perot"], d:"An optical resonator of two parallel, partially reflecting mirrors. Multiple-beam interference gives sharp transmission peaks at resonant frequencies; its sharpness is measured by the finesse F."},
{t:"Jones vector", f:["Jones vector","Jones matrix","Jones matrices"], d:"A two-component complex vector (and 2×2 matrix) describing the polarisation state of fully polarised light and the action of optical elements on it. Wave plates, polarisers and rotators have simple Jones matrices."},
{t:"birefringence", f:["birefringence","birefringent"], d:"The property of anisotropic media (e.g. calcite) of having different refractive indices for different polarisations. It splits light into ordinary and extraordinary rays, the basis of wave plates."},
{t:"retarded potential", f:["retarded potential","retarded potentials"], d:"The potential at (r,t) determined by the source at the retarded time t − |r−r′|/c, since information travels at c. The Liénard–Wiechert potentials are the retarded potentials of a moving point charge."},
{t:"Liénard–Wiechert", f:["Lienard-Wiechert","Liénard–Wiechert"], d:"The exact retarded potentials of a moving point charge. They account for the finite speed of light and yield the full E and B fields, from which the Larmor radiation formula follows."},
{t:"Larmor formula", f:["Larmor formula","Larmor's formula"], d:"The power radiated by an accelerated non-relativistic charge: P = q²a²/(6πε₀c³). Radiation is proportional to the square of the acceleration — hence synchrotron and bremsstrahlung radiation."},
{t:"plasma frequency", f:["plasma frequency"], d:"The natural oscillation frequency of a plasma's electrons, ω_p = √(ne²/mε₀). Waves below ω_p cannot propagate (the plasma is opaque); this governs ionospheric reflection and metal optics."},
{t:"gauge transformation", f:["gauge transformation","gauge invariance","gauge"], d:"The freedom to change A → A + ∇χ, V → V − ∂χ/∂t without altering E and B. Common choices are the Coulomb gauge (∇·A = 0) and the Lorenz gauge (∇·A + (1/c²)∂V/∂t = 0)."},
{t:"Coulomb gauge", f:["Coulomb gauge"], d:"The gauge condition ∇·A = 0. It makes the scalar potential instantaneous (Coulomb's law) and is convenient in radiation problems where only transverse parts of A radiate."},
{t:"Lorenz gauge", f:["Lorenz gauge"], d:"The gauge condition ∇·A + (1/c²)∂V/∂t = 0 that decouples the potentials into wave equations with retarded solutions. It treats V and A on an equal, relativistic footing."},

/* ---------- QUANTUM MECHANICS ---------- */
{t:"wavefunction", f:["wavefunction","wave function","wavefunctions"], d:"The complex function ψ(r,t) that completely describes a quantum state. Its modulus squared |ψ|² gives the probability density, and its time evolution is governed by the Schrödinger equation."},
{t:"Schrödinger equation", f:["Schrödinger equation","Schrodinger equation"], d:"The fundamental equation of non-relativistic quantum mechanics: iħ ∂ψ/∂t = Ĥψ. The time-independent form Ĥψ = Eψ gives stationary states; Ĥ = p̂²/2m + V is the Hamiltonian operator."},
{t:"Born interpretation", f:["Born interpretation","Born rule"], d:"The postulate that |ψ(r,t)|² dV is the probability of finding the particle in volume dV. It makes ψ a probability amplitude and forces ∫|ψ|²dV = 1 (normalisation)."},
{t:"probability density", f:["probability density"], d:"The function |ψ(r,t)|² giving the probability per unit volume of finding the particle. Its integral over all space is 1, and it satisfies a continuity equation with the probability current."},
{t:"continuity equation", f:["continuity equation"], d:"The equation ∂ρ/∂t + ∇·J = 0 expressing conservation of a quantity. In quantum mechanics ρ = |ψ|² and J = (ħ/2mi)(ψ*∇ψ − ψ∇ψ*), guaranteeing probability is conserved."},
{t:"normalisation", f:["normalisation","normalization","normalised"], d:"The requirement ∫|ψ|²dV = 1 that the total probability is unity. It fixes the overall constant of a wavefunction and is necessary for the Born interpretation."},
{t:"Hilbert space", f:["Hilbert space"], d:"The complete inner-product vector space of quantum states. Kets |ψ⟩ are its vectors, bras ⟨φ| its duals, and the inner product ⟨φ|ψ⟩ is the probability amplitude; observables are Hermitian operators on it."},
{t:"ket", f:["ket","kets","bra","bras","Dirac notation","bra-ket"], d:"Dirac notation: a ket |ψ⟩ denotes a state vector in Hilbert space and a bra ⟨φ| its dual. The bracket ⟨φ|ψ⟩ is the inner product (amplitude); operators act as A|ψ⟩."},
{t:"operator", f:["operator","operators"], d:"A map between states, e.g. position, momentum, energy. Observables are represented by Hermitian operators whose eigenvalues are the possible measurement results and whose eigenstates are the corresponding states."},
{t:"Hermitian operator", f:["Hermitian operator","Hermitian","self-adjoint"], d:"An operator satisfying A† = A, i.e. ⟨φ|Aψ⟩ = ⟨Aφ|ψ⟩. Its eigenvalues are real and its eigenvectors orthogonal — hence Hermitian operators represent observables."},
{t:"observable", f:["observable","observables"], d:"A physically measurable quantity, represented by a Hermitian operator. Measurement always yields one of its eigenvalues, with probability |⟨eigenstate|ψ⟩|², and collapses the state onto that eigenstate."},
{t:"eigenvalue", f:["eigenvalue","eigenvalues"], d:"A number λ for which A|ψ⟩ = λ|ψ⟩ has a non-zero solution |ψ⟩ (the eigenvector/eigenstate). The allowed values of an observable are its eigenvalues."},
{t:"eigenstate", f:["eigenstate","eigenstates","eigenfunction","eigenfunctions"], d:"A state |ψ⟩ satisfying A|ψ⟩ = λ|ψ⟩ for an operator A. In an eigenstate the corresponding observable has a definite value λ."},
{t:"expectation value", f:["expectation value","expectation values"], d:"The average result of measuring an observable on a state: ⟨A⟩ = ⟨ψ|A|ψ⟩. It need not be an allowed eigenvalue; repeated measurements scatter about it with variance ⟨A²⟩ − ⟨A⟩²."},
{t:"commutator", f:["commutator","commutators","commutation relation"], d:"The operation [A,B] = AB − BA measuring the failure of operators to commute. The fundamental relation is [x̂,p̂] = iħ; two observables can be simultaneously sharp only if their commutator vanishes."},
{t:"uncertainty principle", f:["uncertainty principle","Heisenberg uncertainty"], d:"The inequality ΔA·ΔB ≥ ½|⟨[A,B]⟩| between the uncertainties of two observables. For position and momentum, Δx·Δp ≥ ħ/2 — conjugate variables cannot both be perfectly sharp."},
{t:"superposition", f:["superposition","superposition principle"], d:"The principle that any linear combination of quantum states is a valid state. Interference between superposed components is the hallmark of quantum mechanics, enabling measurement outcomes to depend on relative phases."},
{t:"measurement", f:["measurement","collapse","wavefunction collapse"], d:"The act of observing an observable. It yields an eigenvalue at random and projects (collapses) the state onto the corresponding eigenstate — the projection postulate."},
{t:"wave-particle duality", f:["wave-particle duality"], d:"The fact that matter and light exhibit both wave and particle behaviour. Electrons show interference (wave) and localised detection (particle); the de Broglie wavelength λ = h/p links the two pictures."},
{t:"de Broglie wavelength", f:["de Broglie wavelength","de Broglie"], d:"λ = h/p, the wavelength associated with a particle of momentum p. It is why electrons diffract from crystals and why matter shows wave behaviour on the atomic scale."},
{t:"wave packet", f:["wave packet","wave packets"], d:"A localised superposition of plane waves. Its envelope moves at the group velocity v_g = dω/dk (the particle velocity), while individual crests move at the phase velocity; it spreads with time due to dispersion."},
{t:"group velocity", f:["group velocity"], d:"v_g = dω/dk, the velocity of the envelope of a wave packet (and of energy transport). For a free quantum particle it equals the particle velocity p/m."},
{t:"phase velocity", f:["phase velocity"], d:"v_p = ω/k, the velocity of a single wave crest. It can exceed c (e.g. for matter waves v_p = c²/v) since it carries no information; only the group velocity is physical."},
{t:"particle in a box", f:["particle in a box","infinite square well","infinite well"], d:"A particle confined between impenetrable walls (V = ∞ outside). Its energies are quantised, Eₙ = n²π²ħ²/(2mL²), and its wavefunctions are standing waves ψₙ ∝ sin(nπx/L)."},
{t:"quantum tunnelling", f:["tunnelling","tunneling","tunnel effect"], d:"The penetration of a particle through a classically forbidden barrier, with transmission probability T ≈ e^{−2κa}. It underlies alpha decay, the tunnel diode and scanning tunnelling microscopy."},
{t:"WKB approximation", f:["WKB approximation","WKB"], d:"The Wentzel–Kramers–Brillouin semiclassical approximation, valid when the potential varies slowly on the de Broglie wavelength. Its quantisation condition is ∮p dx = (n + ½)h, and it gives the tunnelling rate."},
{t:"harmonic oscillator", f:["harmonic oscillator","quantum harmonic oscillator"], d:"The system with potential ½mω²x². Its energies are equally spaced, Eₙ = (n + ½)ħω, and are elegantly obtained with ladder operators a, a†; the ½ħω zero-point energy is a purely quantum effect."},
{t:"ladder operator", f:["ladder operator","ladder operators","raising operator","lowering operator","creation operator","annihilation operator"], d:"Operators that step between adjacent eigenstates: a† (raising/creation) increases the quantum number by one, a (lowering/annihilation) decreases it. They solve the harmonic oscillator and angular-momentum spectra algebraically."},
{t:"zero-point energy", f:["zero-point energy"], d:"The minimum energy ½ħω of a quantum harmonic oscillator (and of any confined quantum system), present even at absolute zero. It is a consequence of the uncertainty principle."},
{t:"ground state", f:["ground state"], d:"The lowest-energy eigenstate of a system. It is nodeless for bound states and is the target of variational and numerical methods."},
{t:"excited state", f:["excited state","excited states"], d:"Any eigenstate above the ground state. Its excess energy is released as radiation or through collisions as the system decays back toward the ground state."},
{t:"degeneracy", f:["degeneracy","degenerate"], d:"The existence of more than one independent eigenstate with the same energy. The hydrogen level n has degeneracy n² (ignoring spin); a perturbation often partially lifts the degeneracy."},
{t:"angular momentum", f:["angular momentum"], d:"The generator of rotations, L = r × p in orbital form, obeying [Lᵢ,Lⱼ] = iħεᵢⱼₖLₖ. Its magnitude is quantised as ħ²l(l+1) and one component as ħm; it is conserved in central potentials."},
{t:"spherical harmonics", f:["spherical harmonics","spherical harmonic"], d:"The angular wavefunctions Y_l^m(θ,φ), eigenstates of L² and L_z. They multiply the radial function in any central-potential solution and determine the angular shapes of atomic orbitals."},
{t:"hydrogen atom", f:["hydrogen atom"], d:"The Coulomb-bound electron–proton system, exactly solvable. Its energies are Eₙ = −13.6 eV/n², its length scale the Bohr radius a₀ = 0.529 Å, and its degeneracy n² (excluding spin)."},
{t:"Bohr radius", f:["Bohr radius"], d:"The natural length scale of the hydrogen atom, a₀ = 4πε₀ħ²/(me²) ≈ 0.529 Å. It is the radius of the n = 1 Bohr orbit and sets the size of all atoms."},
{t:"spin", f:["spin","spin angular momentum"], d:"The intrinsic angular momentum of a particle, unrelated to spatial motion. It is quantised in units of ħ: electrons have spin ½, and spin-½ particles are described by two-component spinors."},
{t:"Pauli matrices", f:["Pauli matrices","Pauli matrix"], d:"The three 2×2 Hermitian matrices σₓ, σ_y, σ_z that represent spin-½ angular momentum via S = (ħ/2)σ. They anticommute, square to the identity, and satisfy σᵢσⱼ = δᵢⱼ + iεᵢⱼₖσₖ."},
{t:"spinor", f:["spinor","spinors"], d:"The two-component vector describing a spin-½ state, e.g. (α, β) for spin up/down. Under a 2π rotation a spinor changes sign — spinors belong to SU(2), the double cover of rotations."},
{t:"Stern–Gerlach experiment", f:["Stern-Gerlach experiment","Stern–Gerlach"], d:"The 1922 experiment sending silver atoms through an inhomogeneous magnetic field. The beam split into two spots, proving spin is quantised (space quantisation) and confirming spin-½."},
{t:"addition of angular momentum", f:["addition of angular momentum","angular momentum addition","Clebsch-Gordan"], d:"The rule J = J₁ + J₂ giving total angular momentum values |j₁−j₂| … j₁+j₂. Clebsch–Gordan coefficients express coupled states in the uncoupled basis; spin–orbit coupling uses J = L + S."},
{t:"perturbation theory", f:["perturbation theory","perturbative"], d:"An approximation scheme for a Hamiltonian Ĥ = Ĥ₀ + λH′. First-order energy corrections are ⟨n|H′|n⟩ (non-degenerate); degenerate levels require diagonalising H′ within the degenerate subspace."},
{t:"variational principle", f:["variational principle","variational method","variational theorem"], d:"The theorem that ⟨H⟩ ≥ E₀ for any trial wavefunction: the ground-state energy is a lower bound on the expectation value. Minimising ⟨H⟩ over a trial family approximates E₀ from above."},
{t:"Fermi's golden rule", f:["Fermi's golden rule","golden rule"], d:"The transition rate formula W = (2π/ħ)|⟨f|H′|i⟩|² ρ(E_f) between states under a perturbation, where ρ(E_f) is the density of final states. It underlies decay rates and absorption cross-sections."},
{t:"selection rule", f:["selection rule","selection rules"], d:"A condition that a transition matrix element be non-zero, set by symmetry. Electric-dipole transitions require Δl = ±1 and Δm = 0, ±1; forbidden transitions violate these and are much weaker."},
{t:"identical particles", f:["identical particles","indistinguishable"], d:"Particles that are fundamentally indistinguishable, so the wavefunction must be symmetric (bosons) or antisymmetric (fermions) under exchange. This single fact underlies the periodic table and Bose–Einstein condensation."},
{t:"Pauli exclusion principle", f:["Pauli exclusion principle"], d:"The principle that two identical fermions cannot occupy the same quantum state. It forces electrons into successive shells, explaining atomic structure, chemical valency and the stability of matter."},
{t:"Slater determinant", f:["Slater determinant","Slater determinants"], d:"The antisymmetrised product wavefunction of N fermions, written as a determinant of single-particle orbitals. It automatically enforces the Pauli principle and is the starting point of the Hartree–Fock method."},
{t:"exchange interaction", f:["exchange interaction","exchange energy"], d:"The energy difference between symmetric and antisymmetric two-particle states arising from wavefunction (anti)symmetry. It is purely quantum — with no classical analogue — and drives ferromagnetism and the helium singlet–triplet splitting."},
{t:"boson", f:["boson","bosons"], d:"A particle of integer spin obeying Bose–Einstein statistics, with a symmetric many-particle wavefunction. Bosons (photons, phonons, mesons, helium-4 atoms) can occupy the same state, enabling lasers and Bose–Einstein condensation."},
{t:"fermion", f:["fermion","fermions"], d:"A particle of half-integer spin obeying Fermi–Dirac statistics, with an antisymmetric wavefunction and Pauli exclusion. Electrons, protons and neutrons are fermions; they form the matter around us."},
{t:"spin-statistics theorem", f:["spin-statistics theorem"], d:"The theorem that integer-spin particles are bosons and half-integer-spin particles are fermions — a relativistic quantum-field-theory result connecting spin to exchange symmetry."},
{t:"Klein–Gordon equation", f:["Klein-Gordon equation","Klein–Gordon"], d:"The relativistic wave equation (∂² + m²c²/ħ²)φ = 0 for spin-0 particles. Its probability density is not positive-definite, a difficulty resolved for spin-½ by the Dirac equation."},
{t:"Dirac equation", f:["Dirac equation"], d:"The relativistic wave equation (iħγ^μ∂_μ − mc)ψ = 0 for spin-½ particles. It predicted antiparticles and the electron's spin-½ and g = 2, and is the foundation of relativistic quantum mechanics."},
{t:"Born approximation", f:["Born approximation"], d:"The first-order (single-scattering) approximation to the scattering amplitude, f(θ) ∝ ∫e^{−iq·r}V(r)d³r, valid for weak potentials. The differential cross-section is |f|²; it generalises to the Fermi golden rule."},
{t:"partial wave analysis", f:["partial wave","partial waves","partial wave analysis"], d:"The expansion of a scattering wavefunction into angular-momentum components e^{iδ_l} sin(kr − lπ/2 + δ_l)/r. Each partial wave acquires a phase shift δ_l, and the total cross-section is σ = (4π/k²)Σ(2l+1)sin²δ_l."},
{t:"optical theorem", f:["optical theorem"], d:"σ_tot = (4π/k) Im f(0): the total cross-section equals the forward scattering amplitude's imaginary part. It expresses the unitarity (flux conservation) of scattering."},

/* ---------- THERMODYNAMICS & STATISTICAL MECHANICS ---------- */
{t:"entropy", f:["entropy"], d:"The measure of disorder, S = k_B ln Ω (Boltzmann), or dS = δQ_rev/T (Clausius). It never decreases in an isolated system (second law); at absolute zero it tends to a constant (third law)."},
{t:"enthalpy", f:["enthalpy"], d:"H = U + PV, the state function natural for constant-pressure processes; ΔH equals the heat absorbed at constant pressure. Its temperature derivative is C_P."},
{t:"Helmholtz free energy", f:["Helmholtz free energy"], d:"F = U − TS, the potential natural for constant (T, V). It equals the maximum extractable work at constant temperature, and F = −kT ln Z links it to the canonical partition function."},
{t:"Gibbs free energy", f:["Gibbs free energy"], d:"G = U + PV − TS = H − TS, natural for constant (T, P). It is minimised at equilibrium and equals the maximum non-PV work; phase equilibria occur where G is equal between phases."},
{t:"chemical potential", f:["chemical potential"], d:"The energy cost of adding one particle, μ = (∂U/∂N)_{S,V} = (∂F/∂N)_{T,V}. It governs particle exchange, phase equilibria and chemical reactions, and sets the Fermi/Bose occupation functions."},
{t:"partition function", f:["partition function","partition functions"], d:"The sum over states Z = Σ e^{−βEᵢ} (canonical) that encodes all thermodynamic information. Free energy F = −kT ln Z, mean energy U = −∂ ln Z/∂β, and fluctuations follow from its derivatives."},
{t:"canonical ensemble", f:["canonical ensemble"], d:"The ensemble of systems exchanging energy with a heat bath at temperature T (N, V, T fixed). States have Boltzmann probabilities pᵢ ∝ e^{−βEᵢ}, with β = 1/kT."},
{t:"microcanonical ensemble", f:["microcanonical ensemble"], d:"The ensemble of isolated systems with fixed (N, V, E). All accessible microstates are equally probable; the number Ω of microstates defines the entropy S = k ln Ω."},
{t:"grand canonical ensemble", f:["grand canonical ensemble"], d:"The ensemble of open systems exchanging both energy and particles (μ, V, T fixed). The grand partition function Ξ determines Φ = −kT ln Ξ and particle-number fluctuations."},
{t:"Boltzmann distribution", f:["Boltzmann distribution","Boltzmann factor"], d:"The probability ∝ e^{−E/kT} that a state of energy E is occupied in thermal equilibrium. The exponential factor e^{−E/kT} is the Boltzmann factor."},
{t:"Maxwell relations", f:["Maxwell relations","Maxwell relation"], d:"The four identities from mixed-partial equality of thermodynamic potentials, e.g. (∂S/∂V)_T = (∂P/∂T)_V. They convert unmeasurable derivatives into measurable response functions."},
{t:"heat capacity", f:["heat capacity","specific heat"], d:"The heat per unit temperature change, C_V = (∂U/∂T)_V or C_P = (∂H/∂T)_P (per mole: specific heat). It measures the system's ability to store thermal energy."},
{t:"latent heat", f:["latent heat"], d:"The heat absorbed or released per unit mass during a first-order phase transition at constant temperature, e.g. heat of fusion or vaporisation. It appears in the Clausius–Clapeyron equation."},
{t:"adiabatic process", f:["adiabatic","adiabatic process"], d:"A process with no heat exchange (δQ = 0). For a reversible adiabat of an ideal gas, PV^γ = constant, with γ = C_P/C_V."},
{t:"isothermal process", f:["isothermal","isothermal process"], d:"A process at constant temperature. For an ideal gas, PV = constant and the work done is W = nRT ln(V₂/V₁)."},
{t:"Carnot cycle", f:["Carnot cycle","Carnot engine"], d:"The ideal reversible cycle of two isotherms and two adiabats. Its efficiency η = 1 − T_c/T_h is the maximum possible between two reservoirs (Carnot's theorem)."},
{t:"Clausius inequality", f:["Clausius inequality"], d:"∮δQ/T ≤ 0 for any cyclic process, equality only if reversible. It defines entropy and is one statement of the second law."},
{t:"Clausius–Clapeyron", f:["Clausius-Clapeyron equation","Clausius–Clapeyron"], d:"dP/dT = L/(TΔv), the slope of a first-order coexistence line in the P–T plane, where L is the latent heat and Δv the specific-volume change. Ice–water has a negative slope because ice is less dense."},
{t:"Joule–Thomson effect", f:["Joule-Thomson effect","Joule–Thomson","throttling"], d:"The temperature change of a gas forced through a porous plug at constant enthalpy. The inversion temperature separates cooling (μ_JT > 0) from heating and underlies gas liquefaction."},
{t:"equipartition theorem", f:["equipartition","equipartition theorem"], d:"Each quadratic degree of freedom contributes ½kT to the mean energy. A monatomic gas has ⟨U⟩ = 3/2 NkT; failures (frozen modes) signal quantum effects."},
{t:"blackbody radiation", f:["blackbody","blackbody radiation"], d:"The thermal radiation in equilibrium inside a cavity. Planck's law gives its spectrum; it obeys the Stefan–Boltzmann law (u ∝ T⁴) and Wien's displacement law, resolving the ultraviolet catastrophe."},
{t:"Planck's law", f:["Planck's law","Planck distribution","Planck spectrum"], d:"The spectral energy density of blackbody radiation, u(ν) ∝ ν³/(e^{hν/kT} − 1), obtained by quantising the oscillator energies. It reduces to Rayleigh–Jeans (low ν) and Wien (high ν) limits."},
{t:"Stefan–Boltzmann law", f:["Stefan-Boltzmann law","Stefan–Boltzmann"], d:"The total radiated power per unit area of a blackbody, E = σT⁴, with σ ≈ 5.67×10⁻⁸ W/m²K⁴. The energy density is u ∝ T⁴."},
{t:"Wien's law", f:["Wien's law","Wien's displacement law","Wien displacement"], d:"λ_max T = b ≈ 2.9×10⁻³ m·K: the peak wavelength of a blackbody spectrum is inversely proportional to temperature."},
{t:"Rayleigh–Jeans law", f:["Rayleigh-Jeans law","Rayleigh–Jeans"], d:"The classical low-frequency limit of blackbody radiation, u(ν) ∝ ν²kT. It diverges at high frequency (the ultraviolet catastrophe), a failure that led to quantisation."},
{t:"Bose–Einstein statistics", f:["Bose-Einstein statistics","Bose–Einstein distribution"], d:"The occupation ⟨n⟩ = 1/(e^{β(ε−μ)} − 1) of bosons. It allows multiple occupation, and below T_c a macroscopic fraction condenses into the ground state (BEC)."},
{t:"Fermi–Dirac statistics", f:["Fermi-Dirac statistics","Fermi–Dirac distribution","Fermi-Dirac"], d:"The occupation ⟨n⟩ = 1/(e^{β(ε−μ)} + 1) of fermions, at most one per state. At T = 0 it is a step at the Fermi energy; at low T only a shell ~kT is excited."},
{t:"Bose–Einstein condensation", f:["Bose-Einstein condensation","BEC"], d:"The macroscopic occupation of the ground state by a Bose gas below T_c ∝ n^{2/3}. It is a purely quantum, interaction-free phase transition observed in ultracold alkali gases."},
{t:"Fermi energy", f:["Fermi energy","Fermi level"], d:"The highest occupied single-particle energy at T = 0, E_F = (ħ²/2m)(3π²n)^{2/3} for a free electron gas. It sets the scale of metals' electronic properties."},
{t:"density of states", f:["density of states"], d:"g(E), the number of states per unit energy. In 3D free space g(E) ∝ E^{1/2}; its form sets the energy-dependence of heat capacities and rates."},
{t:"photon gas", f:["photon gas"], d:"The ensemble of photons in a cavity, bosons with μ = 0. Its pressure is u/3, its entropy ∝ VT³, and its spectrum is the Planck distribution."},
{t:"detailed balance", f:["detailed balance","principle of detailed balance"], d:"The condition that each microscopic process is balanced by its reverse at equilibrium. It links rate constants (Einstein A/B coefficients) and underlies the Boltzmann distribution."},
{t:"fluctuation", f:["fluctuation","fluctuations"], d:"The spontaneous deviation of a quantity from its mean. Energy fluctuations satisfy ⟨(ΔE)²⟩ = kT²C_V; relative fluctuations scale as 1/√N, vanishing in the thermodynamic limit."},
{t:"fluctuation-dissipation theorem", f:["fluctuation-dissipation theorem"], d:"The relation connecting equilibrium fluctuations to linear response: the same physics that damps a system also sets its thermal noise (e.g. Nyquist noise in a resistor)."},
{t:"Onsager relations", f:["Onsager relations","Onsager reciprocal relations"], d:"The symmetry L_ij = L_ji between transport coefficients near equilibrium, e.g. Seebeck and Peltier effects. They reflect microscopic reversibility."},
{t:"Brownian motion", f:["Brownian motion","Brownian"], d:"The random jitter of a particle suspended in a fluid, caused by molecular collisions. Einstein related it to the diffusion coefficient D = kT/(6πηr); mean-square displacement is 2Dt (1D)."},
{t:"diffusion equation", f:["diffusion equation","diffusion"], d:"∂c/∂t = D∇²c, describing the spreading of particles by random motion. Its fundamental solution is a Gaussian whose width grows as √(4Dt)."},
{t:"random walk", f:["random walk"], d:"A path of independent random steps. After N steps of length a the RMS displacement is a√N — the origin of √t spreading in diffusion."},
{t:"mean free path", f:["mean free path"], d:"The average distance a particle travels between collisions, λ = 1/(√2 πd²n) for a hard-sphere gas. It sets transport coefficients (conductivity, viscosity, diffusion)."},
{t:"kinetic theory", f:["kinetic theory","kinetic theory of gases"], d:"The microscopic theory relating gas pressure, temperature and transport to molecular motion. Pressure P = (1/3)nm⟨v²⟩, and v_rms = √(3kT/m)."},
{t:"phase transition", f:["phase transition","phase transitions"], d:"A sharp change in a system's state at a critical point. First-order transitions have a latent heat (melting, boiling); continuous transitions (ferromagnetic, BEC) have divergent fluctuations and critical exponents."},
{t:"order parameter", f:["order parameter"], d:"A quantity that is zero in the disordered phase and non-zero in the ordered phase, e.g. magnetisation in a ferromagnet. Landau theory expands the free energy in it near T_c."},
{t:"critical point", f:["critical point","critical temperature"], d:"The point where a continuous transition occurs; for the liquid–gas system it is the endpoint of the coexistence curve. Fluctuations diverge and the correlation length becomes infinite."},
{t:"critical exponent", f:["critical exponent","critical exponents"], d:"A power-law index describing how a quantity diverges or vanishes near T_c (e.g. C ∝ |t|^{−α}, M ∝ (−t)^β). Exponents are universal — they depend only on dimension and symmetry."},
{t:"Landau theory", f:["Landau theory"], d:"The mean-field theory expanding the free energy in powers of the order parameter, F = F₀ + a m² + b m⁴ + …. It yields continuous or first-order transitions and mean-field critical exponents."},
{t:"Ising model", f:["Ising model"], d:"The lattice model of spins sᵢ = ±1 with energy H = −JΣsᵢsⱼ − hΣsᵢ. It has a phase transition in 2D (exactly solved by Onsager) and 3D, but not in 1D, and is the paradigm of critical phenomena."},
{t:"mean field theory", f:["mean field","mean-field","mean field theory"], d:"The approximation replacing interactions by an average field from all neighbours. For the Ising model it gives T_c = zJ/k and the Curie–Weiss law, but wrong critical exponents in low dimensions."},
{t:"spontaneous symmetry breaking", f:["spontaneous symmetry breaking"], d:"The situation where a system's state has less symmetry than its Hamiltonian. Below T_c a ferromagnet picks a magnetisation direction although the interactions are rotationally symmetric."},
{t:"universality", f:["universality","universality class"], d:"The phenomenon that critical exponents depend only on gross features (spatial dimension and symmetry of the order parameter), not on microscopic details — diverse systems share the same exponents."},

/* ---------- SOLID STATE ---------- */
{t:"crystal lattice", f:["crystal lattice","lattice","Bravais lattice"], d:"The periodic array of points on which a crystal is built, r = n₁a₁ + n₂a₂ + n₃a₃. There are 14 Bravais lattices in 3D, classified into 7 crystal systems."},
{t:"basis", f:["basis","basis atoms"], d:"The group of atoms attached to each lattice point. Crystal structure = lattice + basis; a face-centred cubic lattice with a two-atom basis gives the diamond structure."},
{t:"unit cell", f:["unit cell","primitive cell"], d:"The building block that repeats to form the crystal. A primitive cell contains one lattice point; the Wigner–Seitz cell is a special primitive cell around a lattice point."},
{t:"Miller indices", f:["Miller indices","Miller index"], d:"Integers (hkl) labelling lattice planes: the plane cuts the axes at a/h, b/k, c/l. The spacing between (hkl) planes of a cubic lattice is d = a/√(h² + k² + l²)."},
{t:"reciprocal lattice", f:["reciprocal lattice"], d:"The lattice of wavevectors G with e^{iG·R} = 1 for all lattice vectors R. Diffraction spots occur at reciprocal-lattice points (Laue condition), and Brillouin zones are its Wigner–Seitz cells."},
{t:"Brillouin zone", f:["Brillouin zone","first Brillouin zone"], d:"The Wigner–Seitz cell of the reciprocal lattice. Band gaps open at its boundaries, and all electronic band structure is described within it."},
{t:"structure factor", f:["structure factor"], d:"S(hkl) = Σ fⱼ e^{−iG·rⱼ}, the sum of atomic form factors over the basis. It sets diffraction intensities and causes systematic absences (e.g. FCC only allows all-even or all-odd hkl)."},
{t:"Madelung constant", f:["Madelung constant"], d:"The geometric factor in the electrostatic energy of an ionic crystal, E = −α e²/(4πε₀r). α ≈ 1.748 for NaCl; it sums the Coulomb interactions of all neighbours with alternating signs."},
{t:"ionic bond", f:["ionic bond","ionic crystal"], d:"A bond from electrostatic attraction between oppositely charged ions (e.g. Na⁺Cl⁻). Ionic crystals are insulators with high melting points and strong infrared absorption."},
{t:"covalent bond", f:["covalent bond"], d:"A bond formed by shared electron pairs between atoms (diamond, silicon). Covalent crystals are hard, directional and semiconducting or insulating."},
{t:"van der Waals bond", f:["van der Waals bond","van der Waals"], d:"A weak bond from fluctuating-dipole attraction between neutral atoms/molecules (noble-gas solids). It is described by the Lennard-Jones potential and is weakest of the bond types."},
{t:"Lennard-Jones potential", f:["Lennard-Jones potential","Lennard-Jones"], d:"V(r) = 4ε[(σ/r)¹² − (σ/r)⁶], the standard pair potential with a hard repulsion (r⁻¹²) and van der Waals attraction (r⁻⁶). It models noble gases and molecular solids."},
{t:"phonon", f:["phonon","phonons"], d:"The quantum of lattice vibration. Acoustic phonons describe in-phase motion (sound), optical phonons out-of-phase motion (relevant to infrared absorption); they carry heat and scatter electrons."},
{t:"Debye model", f:["Debye model","Debye"], d:"The model treating lattice vibrations as a continuous elastic medium with a cutoff frequency. It gives the low-temperature heat capacity C ∝ T³ (Debye law) and the Debye temperature."},
{t:"Einstein model", f:["Einstein model","Einstein temperature"], d:"The model of independent oscillators at a single frequency ω_E. It gave the first quantum heat capacity (exponential drop at low T) and the Dulong–Petit limit 3R at high T."},
{t:"Dulong–Petit law", f:["Dulong-Petit law","Dulong–Petit"], d:"The classical result that the molar heat capacity of a solid is 3R ≈ 25 J/mol·K, from equipartition over 3N oscillators. It holds at high temperature but fails at low T."},
{t:"Drude model", f:["Drude model"], d:"The classical free-electron model of metals: electrons are a gas scattering with a relaxation time τ. It gives conductivity σ = ne²τ/m and the Wiedemann–Franz law, but fails for heat capacity and magnetism."},
{t:"Sommerfeld model", f:["Sommerfeld model","Sommerfeld"], d:"The quantum free-electron model treating electrons with Fermi–Dirac statistics. It explains the small linear electronic heat capacity C = (π²/2) Nk (T/T_F) and Pauli paramagnetism."},
{t:"Fermi surface", f:["Fermi surface"], d:"The surface E(k) = E_F in k-space separating occupied from empty states at T = 0. Its shape determines a metal's transport and optical properties."},
{t:"effective mass", f:["effective mass"], d:"m* = ħ²/(d²E/dk²), the mass entering the dynamics of an electron in a band. It can be negative near band maxima, corresponding to hole-like carriers."},
{t:"band gap", f:["band gap","band structure","energy band"], d:"The forbidden energy range between the valence and conduction bands. Its size classifies materials: metals (none), semiconductors (~1 eV, e.g. Si 1.1 eV), insulators (large)."},
{t:"Bloch's theorem", f:["Bloch's theorem","Bloch theorem"], d:"The theorem that eigenfunctions in a periodic potential have the form ψ = e^{ik·r}u(r) with u(r) periodic. It is the foundation of band theory."},
{t:"Kronig–Penney model", f:["Kronig-Penney model","Kronig–Penney"], d:"The solvable 1D model of a periodic square-well (or delta) potential. It shows how allowed bands and forbidden gaps arise from periodicity."},
{t:"tight-binding", f:["tight-binding","tight binding","LCAO"], d:"The approximation building crystal wavefunctions from atomic orbitals (linear combination of atomic orbitals). It gives simple cosine bands, e.g. E(k) = −2t cos(ka) for an s-band."},
{t:"semiconductor", f:["semiconductor","semiconductors"], d:"A material with a band gap ~1 eV whose conductivity rises with temperature. Intrinsic carrier density nᵢ ∝ e^{−Eg/2kT}; doping creates n-type (donors) or p-type (acceptors) conduction."},
{t:"doping", f:["doping","doped","donor","acceptor"], d:"The deliberate addition of impurities to a semiconductor. Donors (e.g. P in Si) supply electrons (n-type); acceptors (e.g. B in Si) supply holes (p-type), controlling conductivity over many orders of magnitude."},
{t:"hole", f:["hole","holes"], d:"The absence of an electron in a nearly full band, behaving as a positive charge carrier. Holes dominate conduction in p-type semiconductors."},
{t:"p-n junction", f:["p-n junction","pn junction"], d:"The interface between p- and n-type semiconductors. A depletion region with a built-in potential forms; it rectifies current and is the basis of diodes, transistors and solar cells."},
{t:"Hall effect", f:["Hall effect"], d:"The transverse voltage across a conductor carrying current in a magnetic field, V_H ∝ IB/nq. Its sign reveals the carrier charge; the Hall coefficient is R_H = 1/nq."},
{t:"superconductivity", f:["superconductivity","superconductor","superconductors"], d:"The zero-resistance state below a critical temperature T_c, accompanied by the Meissner effect (flux expulsion). BCS theory explains it by Cooper pairing of electrons."},
{t:"Meissner effect", f:["Meissner effect"], d:"The complete expulsion of magnetic flux from a superconductor below T_c — a perfect diamagnet with χ = −1. It distinguishes superconductivity from mere perfect conductivity."},
{t:"London equations", f:["London equations","London equation","penetration depth"], d:"The phenomenological equations J = −(n_s e²/m)A describing flux expulsion. They give the penetration depth λ = √(m/(μ₀n_s e²)) over which fields decay at the surface."},
{t:"Cooper pair", f:["Cooper pair","Cooper pairs"], d:"The bound pair of electrons of opposite spin and momentum formed by phonon-mediated attraction. Cooper pairing opens the superconducting gap and is the core of BCS theory."},
{t:"BCS theory", f:["BCS theory","BCS"], d:"The Bardeen–Cooper–Schrieffer microscopic theory of superconductivity. It predicts the gap 2Δ at T=0, T_c ≈ Θ_D e^{−1/N(0)V}, and explains all equilibrium properties."},
{t:"Josephson effect", f:["Josephson effect","Josephson junction"], d:"The tunnelling of Cooper pairs across a thin insulating barrier between superconductors. It produces a zero-voltage supercurrent and, with a voltage, oscillations at frequency 2eV/h."},
{t:"diamagnetism", f:["diamagnetism","diamagnet","diamagnetic"], d:"The weak, negative magnetic response (χ < 0) of all materials from induced currents opposing the field (Lenz). It is temperature-independent and is masked by stronger effects in paramagnets/ferromagnets."},
{t:"paramagnetism", f:["paramagnetism","paramagnet","paramagnetic"], d:"The positive susceptibility χ = C/T (Curie law) of materials with unpaired moments that align with an applied field. Thermal disorder opposes alignment, hence the 1/T falloff."},
{t:"ferromagnetism", f:["ferromagnetism","ferromagnet","ferromagnetic"], d:"The spontaneous parallel alignment of moments below T_c (iron, cobalt, nickel), from exchange interaction. It shows hysteresis and remanent magnetisation, with susceptibility following the Curie–Weiss law above T_c."},
{t:"antiferromagnetism", f:["antiferromagnetism","antiferromagnet","antiferromagnetic"], d:"The antiparallel alignment of neighbouring spins below the Néel temperature T_N (MnO, MnF₂). The net magnetisation is zero, and susceptibility peaks at T_N."},
{t:"ferrimagnetism", f:["ferrimagnetism","ferrimagnet","ferrite"], d:"Antiparallel alignment of unequal sublattice moments (ferrites such as Fe₃O₄). A net magnetisation survives below T_c; ferrites are insulating magnets used in cores and microwave devices."},
{t:"Curie law", f:["Curie law","Curie's law"], d:"χ = C/T, the inverse-temperature susceptibility of a paramagnet, derived from the Langevin/Brillouin function at high temperature."},
{t:"Curie–Weiss law", f:["Curie-Weiss law","Curie–Weiss"], d:"χ = C/(T − T_c), the susceptibility of a ferromagnet above T_c, signalling the onset of ordering at T_c through the molecular field."},
{t:"hysteresis", f:["hysteresis","hysteresis loop"], d:"The loop traced by magnetisation M versus applied field H in a ferromagnet. Its features — remanence M_r and coercivity H_c — and its enclosed area (energy loss per cycle) define hard vs soft magnets."},
{t:"magnetic domain", f:["magnetic domain","magnetic domains","Bloch wall"], d:"A region of uniform magnetisation in a ferromagnet, separated by domain (Bloch) walls. Domains minimise the magnetostatic energy; their growth and reorientation produce hysteresis."},
{t:"Pauli paramagnetism", f:["Pauli paramagnetism"], d:"The small, temperature-independent paramagnetism of conduction electrons. Only a fraction ~T/T_F of electrons near the Fermi surface can flip, giving χ_P ∝ g(E_F)."},

/* ---------- NUCLEAR & PARTICLE ---------- */
{t:"nucleon", f:["nucleon","nucleons"], d:"A proton or neutron — a constituent of the atomic nucleus. Nucleons are bound by the strong nuclear force and are themselves made of quarks."},
{t:"isotope", f:["isotope","isotopes"], d:"Nuclei with the same atomic number Z (same element) but different neutron number N, e.g. ¹²C and ¹⁴C. They have identical chemistry but different nuclear properties."},
{t:"isobar", f:["isobar","isobars"], d:"Nuclei with the same mass number A but different Z, e.g. ¹⁴C and ¹⁴N. Beta decay connects neighbouring isobars."},
{t:"isotone", f:["isotone","isotones"], d:"Nuclei with the same neutron number N but different Z."},
{t:"binding energy", f:["binding energy","mass defect"], d:"The energy that would be needed to separate a nucleus into free nucleons: B = (Zm_p + Nm_n − M)c². The mass defect is the corresponding mass difference."},
{t:"semi-empirical mass formula", f:["semi-empirical mass formula","liquid drop model","Weizsäcker formula"], d:"The formula expressing nuclear binding energy as volume, surface, Coulomb, asymmetry and pairing terms. It reproduces the B/A curve and explains fission and the valley of stability."},
{t:"magic number", f:["magic number","magic numbers"], d:"Nucleon numbers 2, 8, 20, 28, 50, 82, 126 at which nuclei are especially stable — the nuclear analogue of closed electron shells. They arise from the spin-orbit force in the shell model."},
{t:"shell model", f:["shell model","nuclear shell model"], d:"The model in which nucleons fill single-particle orbitals in a common potential. Adding a strong spin–orbit term reproduces the magic numbers and the ground-state spins and parities of nuclei."},
{t:"nuclear force", f:["nuclear force","strong force","strong interaction"], d:"The short-range (~1 fm) attractive force between nucleons. It is charge-independent, saturates, and has a strong spin-dependence; at long range it is described by Yukawa's pion exchange."},
{t:"Yukawa potential", f:["Yukawa potential","Yukawa"], d:"V(r) = −g²e^{−r/R}/r, the potential from exchange of a meson of Compton wavelength R = ħ/mc. It predicted the pion: a range of ~1 fm implies a meson mass ~140 MeV/c²."},
{t:"deuteron", f:["deuteron","deuterium"], d:"The nucleus of deuterium, a proton and neutron bound by ~2.2 MeV. It has spin 1 and positive parity, a small quadrupole moment (D-state admixture), and no excited bound states."},
{t:"alpha decay", f:["alpha decay","alpha particle"], d:"The emission of a helium-4 nucleus, described by Gamow's quantum tunnelling through the Coulomb barrier. The Geiger–Nuttall law relates half-life to the decay energy."},
{t:"beta decay", f:["beta decay","beta-minus","beta-plus","electron capture"], d:"Weak-interaction conversion of a nucleon: n → p + e⁻ + ν̄ (β⁻), p → n + e⁺ + ν (β⁺), or electron capture. It preserves A and shifts Z by ±1, with a continuous electron energy spectrum."},
{t:"gamma decay", f:["gamma decay","gamma ray","gamma-ray"], d:"The emission of a high-energy photon as a nucleus de-excites between levels. Transitions are classified by multipolarity (E1, M1, E2…) with parity and angular-momentum selection rules."},
{t:"half-life", f:["half-life","half life"], d:"The time for half of a radioactive sample to decay, T_{1/2} = ln 2/λ, where λ is the decay constant. Activity falls as A = A₀ e^{−λt}."},
{t:"decay constant", f:["decay constant"], d:"λ, the probability per unit time of decay of a nucleus. Activity A = λN, and mean lifetime is τ = 1/λ."},
{t:"activity", f:["activity"], d:"The number of decays per second, A = λN, measured in becquerels (1 Bq = 1 s⁻¹) or curies (1 Ci = 3.7×10¹⁰ Bq)."},
{t:"Fermi theory", f:["Fermi theory","Fermi theory of beta decay","Kurie plot"], d:"The theory of beta decay treating the interaction as a point contact current–current coupling. It gives the energy spectrum and the Kurie plot — a straight-line representation used to measure the endpoint energy."},
{t:"fission", f:["fission","nuclear fission"], d:"The splitting of a heavy nucleus (e.g. ²³⁵U) into two medium fragments plus neutrons and ~200 MeV. The liquid-drop (Bohr–Wheeler) model describes the deformation barrier; chain reactions enable reactors and bombs."},
{t:"fusion", f:["fusion","nuclear fusion"], d:"The merging of light nuclei (e.g. d + t → ⁴He + n, releasing 17.6 MeV). It powers stars; overcoming the Coulomb barrier requires extreme temperature or quantum tunnelling."},
{t:"Q-value", f:["Q-value","Q value"], d:"The energy released in a reaction, Q = (m_initial − m_final)c². Q > 0 is exothermic; for endothermic reactions the threshold kinetic energy exceeds |Q| by the recoil factor."},
{t:"threshold energy", f:["threshold energy","threshold"], d:"The minimum projectile kinetic energy for an endothermic reaction to proceed, T_th = |Q|(1 + m₁/m₂) in the lab frame for a target at rest. It is derived from energy–momentum conservation."},
{t:"Breit–Wigner formula", f:["Breit-Wigner","Breit–Wigner formula"], d:"The resonance cross-section σ ∝ Γ²/[(E − E₀)² + Γ²/4] near a compound-nucleus resonance of width Γ. It is the nuclear analogue of a driven damped oscillator."},
{t:"compound nucleus", f:["compound nucleus"], d:"The long-lived intermediate state (Bohr, 1936) in which an incident particle's energy is shared among all nucleons before decay. Its decay is independent of how it was formed."},
{t:"quark", f:["quark","quarks"], d:"The fundamental spin-½ constituent of hadrons, in six flavours (u, d, c, s, t, b) with fractional charge. Quarks carry colour charge and are confined; they combine into mesons (qq̄) and baryons (qqq)."},
{t:"lepton", f:["lepton","leptons"], d:"A fundamental spin-½ particle that does not feel the strong force: electron, muon, tau and their neutrinos. Lepton number is conserved in the standard model."},
{t:"hadron", f:["hadron","hadrons"], d:"A composite particle made of quarks bound by the strong force. Mesons (integer spin) and baryons (half-integer spin) are the two families."},
{t:"meson", f:["meson","mesons"], d:"A quark–antiquark bound state of integer spin (pion, kaon). Mesons mediate the residual nuclear force, e.g. pion exchange between nucleons."},
{t:"baryon", f:["baryon","baryons"], d:"A three-quark bound state of half-integer spin (proton, neutron, Λ, Σ, Ξ). Baryon number B is conserved in all standard-model processes."},
{t:"strangeness", f:["strangeness","strange"], d:"The quantum number S counting strange quarks, conserved by strong and electromagnetic interactions but violated by weak decays. The Gell-Mann–Nishijima formula Q = I₃ + (B + S)/2 links it to charge."},
{t:"isospin", f:["isospin"], d:"The approximate SU(2) symmetry treating proton and neutron (or up and down quarks) as two states of one particle. It organises hadrons into multiplets, e.g. the pion triplet."},
{t:"parity", f:["parity"], d:"The symmetry under spatial inversion r → −r. States have parity ±1; parity is conserved by strong and electromagnetic interactions but violated by the weak interaction (Wu's experiment)."},
{t:"charge conjugation", f:["charge conjugation","C-parity"], d:"The symmetry under particle–antiparticle interchange. It is conserved in strong and electromagnetic interactions; combined with parity and time reversal it forms the CPT theorem."},
{t:"CP violation", f:["CP violation","CPT theorem"], d:"The violation of the combined charge-parity symmetry, observed in neutral kaon and B-meson decays. The CPT theorem guarantees the combined CPT symmetry of any local field theory."},
{t:"neutrino", f:["neutrino","neutrinos","antineutrino"], d:"A nearly massless, chargeless spin-½ lepton interacting only weakly. Neutrinos are left-handed (helicity −1), and flavour oscillations imply small but non-zero masses."},
{t:"helicity", f:["helicity"], d:"The projection of spin along momentum, h = (σ·p)/p. Massless fermions have fixed helicity; the weak interaction couples only to left-handed particles, a signature of parity violation."},
{t:"weak interaction", f:["weak interaction","weak force"], d:"The short-range force mediated by W and Z bosons, responsible for beta decay and neutrino interactions. It is the only force that violates parity and can change quark flavour."},
{t:"standard model", f:["standard model","Standard Model"], d:"The gauge theory of the strong (SU(3)) and electroweak (SU(2)×U(1)) forces, with three generations of quarks and leptons and the Higgs mechanism generating mass. It is the current fundamental theory of particle physics."},
{t:"Mandelstam variables", f:["Mandelstam variables","Mandelstam"], d:"The Lorentz-invariant combinations s = (p₁+p₂)², t = (p₁−p₃)², u = (p₁−p₄)² describing two-body scattering, with s + t + u = Σm². Thresholds and cross-sections are expressed in them."},
{t:"pair production", f:["pair production"], d:"The conversion of a photon (energy > 2m_ec² = 1.022 MeV) into an electron–positron pair in the field of a nucleus. It is the dominant photon interaction above ~5 MeV."},
{t:"annihilation", f:["annihilation","annihilate"], d:"The conversion of a particle and its antiparticle into photons or other particles. Electron–positron annihilation yields two 0.511 MeV photons (back-to-back in the rest frame)."},

/* ---------- ATOMIC & MOLECULAR ---------- */
{t:"Bohr model", f:["Bohr model"], d:"The semiclassical model of the hydrogen atom with quantised angular momentum mvr = nħ. It gives Eₙ = −13.6 eV/n² and explained the Balmer spectrum; it was superseded by the Schrödinger equation."},
{t:"Rydberg constant", f:["Rydberg constant","Rydberg"], d:"R = m e⁴/(8ε₀²h³c) ≈ 1.097×10⁷ m⁻¹, the constant in the spectral formula 1/λ = R(1/n₁² − 1/n₂²) of hydrogen."},
{t:"fine structure", f:["fine structure","fine structure constant"], d:"The small splitting of atomic levels from relativistic kinetic-energy correction, spin–orbit coupling and the Darwin term — all of order α² times the gross energy. The fine-structure constant α = e²/(4πε₀ħc) ≈ 1/137."},
{t:"spin–orbit coupling", f:["spin-orbit coupling","spin–orbit"], d:"The interaction H_SO ∝ L·S between a particle's orbital and spin angular momenta. In atoms it splits levels by J = L ± S; in nuclei it is strong and produces the magic numbers."},
{t:"hyperfine structure", f:["hyperfine structure","hyperfine"], d:"The very small splitting from coupling of electron and nuclear spins (F = I + J), ~10⁻⁶ of the fine structure. The 21-cm hydrogen line is a hyperfine transition."},
{t:"Lamb shift", f:["Lamb shift"], d:"The tiny splitting between 2S₁/₂ and 2P₁/₂ of hydrogen, from vacuum (quantum-electrodynamic) effects. Its measurement founded quantum electrodynamics."},
{t:"quantum defect", f:["quantum defect"], d:"The correction δ_l subtracted from n in alkali-atom energy levels E = −13.6/(n−δ_l)², accounting for core penetration by the valence electron. It is large for s-states and small for high l."},
{t:"Zeeman effect", f:["Zeeman effect","normal Zeeman","anomalous Zeeman"], d:"The splitting of spectral lines in a magnetic field. Normal Zeeman (S = 0) gives a triplet split by μ_B B; anomalous Zeeman (S ≠ 0) gives a more complex pattern governed by the Landé g-factor."},
{t:"Paschen–Back effect", f:["Paschen-Back effect","Paschen–Back"], d:"The regime of a strong magnetic field, where the field decouples L and S (spin–orbit broken). Levels split as m_l and m_s separately, and the anomalous pattern goes over to the normal triplet."},
{t:"Stark effect", f:["Stark effect"], d:"The splitting of spectral lines in an electric field. Hydrogen (degenerate) shows a linear Stark shift; non-degenerate states show a quadratic shift."},
{t:"LS coupling", f:["LS coupling","Russell-Saunders","Russell–Saunders"], d:"The coupling scheme (light atoms) where orbital angular momenta combine to L and spins to S, then L + S = J. States are labelled by term symbols ²S⁺¹L_J."},
{t:"jj coupling", f:["jj coupling","j-j coupling"], d:"The coupling scheme (heavy atoms) where each electron's l and s first combine to jᵢ, then the jᵢ combine to total J. It applies when spin–orbit dominates residual electrostatic terms."},
{t:"term symbol", f:["term symbol","term symbols"], d:"The label ²S⁺¹L_J of an atomic state: multiplicity 2S+1, orbital letter, total angular momentum J. Hund's rules determine the ground-state term."},
{t:"Hund's rules", f:["Hund's rules","Hund rule"], d:"The rules for the ground term: maximise S, then L, then choose J = |L − S| for less-than-half-filled shells and L + S for more-than-half-filled."},
{t:"ESR", f:["ESR","electron spin resonance","EPR"], d:"Electron spin resonance: absorption of microwaves when ħω = gμ_B B, flipping electron spins in a magnetic field. The hyperfine interaction splits lines into 2NI + 1 components."},
{t:"NMR", f:["NMR","nuclear magnetic resonance"], d:"Nuclear magnetic resonance: absorption at the Larmor frequency ω = g_I μ_N B/ħ by nuclear spins. Chemical shift and J-coupling make it the premier tool of molecular structure."},
{t:"Larmor precession", f:["Larmor precession","Larmor frequency"], d:"The precession of a magnetic moment about an external field at angular frequency ω = γB. It underlies ESR, NMR and the Zeeman effect."},
{t:"g-factor", f:["g-factor","gyromagnetic ratio","Landé g-factor"], d:"The proportionality between magnetic moment and angular momentum, μ = g q/(2m) J. For electron spin g ≈ 2.0023; the Landé g-factor interpolates orbital (1) and spin (2) for a general J."},
{t:"Raman scattering", f:["Raman scattering","Raman effect","Raman"], d:"Inelastic scattering of light with vibrational/rotational excitations of molecules. Stokes lines (lower frequency) and anti-Stokes lines (higher) flank the elastic Rayleigh line."},
{t:"Rayleigh scattering", f:["Rayleigh scattering"], d:"Elastic scattering of light by particles much smaller than the wavelength, with cross-section ∝ 1/λ⁴. It explains the blue sky and red sunsets."},
{t:"Stokes shift", f:["Stokes line","anti-Stokes","Stokes shift"], d:"The frequency difference between absorbed and emitted light in fluorescence/Raman processes. Stokes emission has lower energy than absorption (energy lost to vibrations); anti-Stokes is higher."},
{t:"Franck–Condon principle", f:["Franck-Condon principle","Franck–Condon"], d:"The principle that electronic transitions occur so rapidly that nuclear positions are unchanged (vertical transitions). Transition intensities are set by the overlap (Franck–Condon factor) of vibrational wavefunctions."},
{t:"Born–Oppenheimer approximation", f:["Born-Oppenheimer approximation","Born–Oppenheimer"], d:"The separation of electronic and nuclear motion justified by the large electron-to-nucleus mass ratio. It lets one solve the electronic problem at fixed nuclear positions first."},
{t:"rigid rotor", f:["rigid rotor","rigid rotator"], d:"The model of a rotating diatomic with fixed bond length. Its levels are E_J = BJ(J+1) with B = ħ²/2I, giving a spectrum of equally spaced lines (2B)."},
{t:"Morse potential", f:["Morse potential","anharmonicity","anharmonic"], d:"V(r) = D(1 − e^{−a(r−r₀)})², the standard anharmonic oscillator potential of a diatomic. Its levels E_v = ħω(v + ½) − ħωxₑ(v + ½)² converge to the dissociation energy D."},
{t:"centrifugal distortion", f:["centrifugal distortion","non-rigid rotor"], d:"The stretching of a rotating molecule at high J, lowering the rotational constant: E_J = BJ(J+1) − DJ²(J+1)²."},
{t:"P-branch", f:["P-branch","Q-branch","R-branch"], d:"The rotational sub-branches of a vibration–rotation band: P (ΔJ = −1), Q (ΔJ = 0) and R (ΔJ = +1). P and R form the characteristic double-lobed envelope; Q appears when parallel transitions allow ΔJ = 0."},
{t:"dissociation energy", f:["dissociation energy"], d:"The energy required to separate a molecule into its atoms, D. For the Morse potential it is the limit of the vibrational ladder, measurable by the Birge–Sponer extrapolation."},
{t:"laser", f:["laser","lasers"], d:"A source of coherent, monochromatic light via stimulated emission. It requires population inversion between levels and an optical resonator; three- and four-level systems are the standard pumping schemes."},
{t:"population inversion", f:["population inversion"], d:"The condition that an upper level is more populated than a lower one (N₂ > N₁), necessary for net stimulated emission (laser gain). It is achieved by optical pumping or electrical excitation."},
{t:"stimulated emission", f:["stimulated emission","spontaneous emission"], d:"The emission of a photon triggered by an incident photon, producing an identical second photon in phase and direction. It is the gain mechanism of lasers, governed by Einstein's B coefficient (spontaneous emission is random, with coefficient A)."},
{t:"Einstein coefficients", f:["Einstein coefficients","Einstein A","Einstein B"], d:"The rates A₂₁ (spontaneous emission), B₁₂ (absorption) and B₂₁ (stimulated emission) linking radiative transitions. Thermodynamic equilibrium forces B₁₂ = B₂₁ and A₂₁/B₂₁ = ħω³/π²c³."},
{t:"coherence length", f:["coherence length","coherence time"], d:"The distance (L_c = c τ_c) over which a wave maintains a definite phase. It is inversely proportional to the spectral width Δλ; lasers have long coherence lengths, thermal sources short."},
{t:"Doppler broadening", f:["Doppler broadening","natural broadening","Voigt profile"], d:"The broadening of spectral lines: Doppler (Gaussian) from the thermal motion of emitters, natural (Lorentzian) from the finite lifetime of the excited state. Their convolution is the Voigt profile."},
{t:"X-ray", f:["X-ray","X-rays","x-ray"], d:"Electromagnetic radiation of wavelength ~0.01–10 Å, from inner-shell transitions (characteristic lines) and electron deceleration (bremsstrahlung). The Duane–Hunt law sets λ_min = hc/eV."},
{t:"bremsstrahlung", f:["bremsstrahlung"], d:"The continuous radiation emitted when charged particles decelerate in the Coulomb field of nuclei (German for 'braking radiation'). Its spectrum is continuous up to the particle's kinetic energy."},
{t:"Auger effect", f:["Auger effect","Auger electron"], d:"The radiationless relaxation of an inner-shell vacancy: the energy released by an electron dropping into the hole ejects a second electron. It dominates over X-ray emission in light elements."},
{t:"Moseley's law", f:["Moseley's law","Moseley law"], d:"√ν ∝ (Z − b) for characteristic X-ray lines: the square root of the frequency is linear in atomic number. It established Z as the ordering principle of the periodic table."},
{t:"photoelectric effect", f:["photoelectric effect"], d:"The ejection of electrons from matter by light, explained by Einstein: each photon of energy hν transfers its energy to one electron, with E_max = hν − φ (the work function)."},
{t:"Compton scattering", f:["Compton scattering","Compton effect"], d:"The inelastic scattering of a photon by a free electron, λ′ − λ = (h/mc)(1 − cosθ). It confirmed the photon's particle nature and is a dominant gamma-ray interaction at intermediate energies."},

/* ---------- MATHEMATICAL PHYSICS ---------- */
{t:"gradient", f:["gradient"], d:"The vector operator ∇f pointing in the direction of steepest increase of a scalar field, with magnitude equal to its rate of change. In physics it gives the force F = −∇V."},
{t:"divergence", f:["divergence"], d:"∇·F, the scalar measure of a vector field's sources (net outward flux per unit volume). ∇·E = ρ/ε₀ in electrostatics; a field with zero divergence is solenoidal."},
{t:"curl", f:["curl"], d:"∇×F, the vector measure of a field's circulation per unit area. ∇×B = μ₀J in magnetostatics; a curl-free field is irrotational and derivable from a potential."},
{t:"Laplacian", f:["Laplacian"], d:"∇² = ∇·∇, the divergence of the gradient. It appears in Laplace's, Poisson's, wave and diffusion equations, and measures the departure of a field from its average."},
{t:"divergence theorem", f:["divergence theorem","Gauss theorem","Gauss's theorem"], d:"∫∇·F dV = ∮F·dA: the volume integral of a divergence equals the flux through the boundary surface. It converts Gauss's law into a differential equation."},
{t:"Stokes' theorem", f:["Stokes' theorem","Stokes theorem"], d:"∫(∇×F)·dA = ∮F·dl: the surface integral of a curl equals the circulation around the boundary. It connects Faraday's and Ampère's integral and differential forms."},
{t:"delta function", f:["delta function","Dirac delta","Dirac delta function"], d:"The distribution δ(x) that is zero except at x = 0 with ∫δ(x)dx = 1. It represents point charges, impulses and density of a single state; under a change of variables, δ(g(x)) = Σδ(x−xᵢ)/|g′(xᵢ)|."},
{t:"orthogonality", f:["orthogonality","orthogonal","orthonormal"], d:"The vanishing inner product ⟨u|v⟩ = 0 between vectors/functions. Orthogonal (especially orthonormal) sets form convenient bases; eigenvectors of Hermitian operators are orthogonal."},
{t:"matrix", f:["matrix","matrices"], d:"A rectangular array of numbers representing a linear transformation. Its determinant, trace and eigenvalues are invariant data; matrices are the natural language of linear algebra and quantum mechanics."},
{t:"determinant", f:["determinant"], d:"The scalar det(A) of a square matrix, the signed volume scaling of the transformation. It is zero exactly when the matrix is singular (non-invertible); it factors as the product of eigenvalues."},
{t:"trace", f:["trace"], d:"The sum of diagonal elements of a matrix, equal to the sum of its eigenvalues. It is invariant under similarity transformations and satisfies tr(AB) = tr(BA)."},
{t:"diagonalisation", f:["diagonalisation","diagonalization","diagonalise","diagonalize"], d:"The transformation of a matrix to diagonal form via a similarity transformation of its eigenvectors. A matrix is diagonalisable by a unitary matrix exactly when it is normal (e.g. Hermitian)."},
{t:"unitary matrix", f:["unitary matrix","unitary"], d:"A matrix satisfying U†U = I, preserving inner products and lengths. Unitary operators represent symmetry transformations and time evolution in quantum mechanics."},
{t:"orthogonal matrix", f:["orthogonal matrix","orthogonal transformation"], d:"A real matrix with OᵀO = I, representing rotations and reflections. Its determinant is ±1; proper rotations have det = +1."},
{t:"Cayley–Hamilton theorem", f:["Cayley-Hamilton theorem","Cayley–Hamilton"], d:"The theorem that every square matrix satisfies its own characteristic equation. It is used to compute matrix functions like e^{θA} as polynomials in A."},
{t:"metric tensor", f:["metric tensor","metric"], d:"g_{μν}, the tensor defining distances ds² = g_{μν}dx^μdx^ν. It is diag(1,−1,−1,−1) in Minkowski space and encodes the geometry of curved spacetime in general relativity."},
{t:"tensor", f:["tensor","tensors"], d:"A multi-index quantity transforming linearly under coordinate changes: scalars (rank 0), vectors (rank 1), matrices (rank 2). Physical laws are tensor equations and so are form-invariant in all frames."},
{t:"contravariant", f:["contravariant","covariant"], d:"The two transformation types of tensor indices: contravariant (upper index, like dx^μ) and covariant (lower index, like ∂_μ). The metric tensor raises and lowers indices between them."},
{t:"Christoffel symbol", f:["Christoffel symbol","Christoffel symbols"], d:"Γ^λ_{μν}, the connection coefficients built from the metric that define parallel transport and the covariant derivative. They vanish in flat space with Cartesian coordinates."},
{t:"covariant derivative", f:["covariant derivative"], d:"∇_ν, the derivative that transforms as a tensor, including the connection terms. It generalises the ordinary derivative to curved spaces and non-Cartesian coordinates."},
{t:"group", f:["group","subgroup","Abelian group"], d:"A set with an associative operation, identity and inverses. Symmetry groups classify physical systems: rotations SO(3), Lorentz SO(3,1), gauge groups SU(3)×SU(2)×U(1)."},
{t:"Lie group", f:["Lie group","Lie algebra"], d:"A continuous group with a differentiable manifold structure. Its infinitesimal generators form a Lie algebra with structure constants; SO(3) and SU(2) share the same Lie algebra, the angular-momentum algebra."},
{t:"SO(3)", f:["SO(3)"], d:"The group of proper rotations in three dimensions. Its representations are labelled by angular momentum l; it is double-covered by SU(2), so spin-½ (SU(2)) exists."},
{t:"SU(2)", f:["SU(2)"], d:"The group of 2×2 unitary matrices with determinant 1, the symmetry group of spin. It double-covers SO(3): a 2π rotation changes a spinor's sign but returns SO(3) to the identity."},
{t:"representation", f:["representation","representations","irreducible"], d:"A realisation of a group as matrices acting on a vector space. Irreducible representations (irreps) are the building blocks; they label the states of quantum systems by symmetry."},
{t:"Fourier series", f:["Fourier series"], d:"The expansion of a periodic function in sines and cosines (or complex exponentials) with coefficients given by the Euler formulas. It decomposes signals into harmonics; Gibbs oscillations occur at discontinuities."},
{t:"Fourier transform", f:["Fourier transform","Fourier transforms"], d:"The integral transform f̃(k) = ∫f(x)e^{−ikx}dx that maps between position and wavenumber (or time and frequency). It diagonalises translation-invariant operators and underpins wave mechanics."},
{t:"Parseval's theorem", f:["Parseval's theorem","Parseval"], d:"The statement that the total energy/power of a signal is preserved between a function and its Fourier transform: ∫|f|² = (1/2π)∫|f̃|². It is the energy form of orthogonality."},
{t:"convolution", f:["convolution"], d:"The operation (f∗g)(x) = ∫f(x−y)g(y)dy combining two functions. It becomes multiplication under Fourier transform — the basis of linear filters and Green's-function solutions."},
{t:"Laplace transform", f:["Laplace transform","Laplace transforms"], d:"F(s) = ∫f(t)e^{−st}dt, mapping functions of time to functions of the complex variable s. It turns differential equations into algebraic ones, ideal for initial-value problems."},
{t:"residue", f:["residue","residues"], d:"The coefficient of the (z − z₀)⁻¹ term in a Laurent expansion. The residue theorem evaluates contour integrals as 2πi times the sum of residues of enclosed poles."},
{t:"analytic function", f:["analytic function","analytic","holomorphic"], d:"A complex function differentiable in a neighbourhood of a point, hence infinitely differentiable and expandable in a power series. Analyticity plus the Cauchy–Riemann equations are equivalent."},
{t:"singularity", f:["singularity","singularities","pole"], d:"A point where a complex function fails to be analytic. Isolated singularities are removable, poles (finite-order divergence) or essential; the order of a pole sets the residue calculation."},
{t:"Laurent series", f:["Laurent series"], d:"The expansion of a function about a singular point in positive and negative powers, f(z) = Σ aₙ(z − z₀)ⁿ. The a₋₁ coefficient is the residue."},
{t:"Cauchy's integral formula", f:["Cauchy's integral formula","Cauchy's theorem","residue theorem"], d:"f(z₀) = (1/2πi)∮f(z)/(z−z₀)dz: an analytic function is determined inside a contour by its boundary values. Cauchy's theorem states the integral around a closed curve of an analytic function vanishes; the residue theorem generalises both to meromorphic functions."},
{t:"Legendre polynomials", f:["Legendre polynomials","Legendre polynomial"], d:"Pₙ(x), the orthogonal polynomial solutions of the Legendre equation, arising in spherical harmonics and multipole expansions. They satisfy Rodrigues' formula and generate the angular structure of central-potential problems."},
{t:"Bessel functions", f:["Bessel function","Bessel functions"], d:"J_ν(x), the solutions of Bessel's equation, arising in cylindrical coordinates, waveguides and diffraction. They are oscillatory, orthogonal with weight x, and appear in Fourier–Bessel expansions."},
{t:"Hermite polynomials", f:["Hermite polynomials","Hermite polynomial"], d:"Hₙ(x), the orthogonal polynomials of the quantum harmonic oscillator (with weight e^{−x²}). They give the oscillator wavefunctions ψₙ ∝ e^{−x²/2}Hₙ(x)."},
{t:"Laguerre polynomials", f:["Laguerre polynomials","Laguerre"], d:"Lₙ(x) and associated Lₙ^k(x), the orthogonal polynomials of the radial hydrogen wavefunction. They arise from the radial Schrödinger equation for the Coulomb potential."},
{t:"Sturm–Liouville theory", f:["Sturm-Liouville","Sturm–Liouville"], d:"The theory of eigenvalue problems (py′)′ + qy + λwy = 0 with boundary conditions. Its eigenfunctions are orthogonal with weight w(x) and form a complete basis — the common structure of special functions."},
{t:"Green's function", f:["Green's function","Green function","Green's functions"], d:"The impulse response G(x,x′) of a linear differential operator, satisfying LG = δ(x − x′). The solution for any source is the convolution of the source with G; it is the inverse of the operator."},
{t:"boundary value problem", f:["boundary value problem","boundary conditions"], d:"A differential equation solved with conditions on the solution at the domain boundary (Dirichlet fixes values, Neumann fixes derivatives). Uniqueness requires well-posed conditions."},
{t:"separation of variables", f:["separation of variables"], d:"The technique of writing a solution as a product of single-variable functions, reducing a PDE to ordinary differential equations. It works for linear PDEs in separable coordinates."},
{t:"wave equation", f:["wave equation"], d:"∂²u/∂t² = c²∇²u, the hyperbolic equation of wave propagation. Its general 1D solution is d'Alembert's u = f(x − ct) + g(x + ct)."},
{t:"heat equation", f:["heat equation"], d:"∂u/∂t = α∇²u, the parabolic equation of diffusion and heat conduction. Its fundamental solution is a Gaussian that spreads with √t."},
{t:"elliptic", f:["elliptic","parabolic","hyperbolic"], d:"The classification of second-order PDEs by their characteristics: elliptic (Laplace — equilibrium), parabolic (diffusion — one characteristic), hyperbolic (wave — two real characteristics). The type sets the required boundary data."},
{t:"random variable", f:["random variable","random variables"], d:"A quantity whose value is a random outcome of an experiment. Discrete variables have a probability mass function, continuous ones a density; they are characterised by expectation and variance."},
{t:"expectation value", f:["expectation","expectation value","variance","standard deviation"], d:"Statistical moments of a random variable: the expectation (mean) E[X] locates it, the variance Var(X) = E[X²] − E[X]² measures spread, and the standard deviation is its square root."},
{t:"binomial distribution", f:["binomial distribution","binomial"], d:"The distribution of successes in n independent trials with success probability p: P(k) = C(n,k)p^k(1−p)^{n−k}. Its mean is np and variance np(1−p)."},
{t:"Poisson distribution", f:["Poisson distribution","Poisson"], d:"The distribution of rare, independent events in a fixed interval: P(k) = λ^k e^{−λ}/k!. Mean and variance both equal λ; it is the limit of the binomial for large n, small p."},
{t:"Gaussian distribution", f:["Gaussian distribution","Gaussian","normal distribution"], d:"The bell-shaped distribution f(x) = (1/σ√2π) e^{−(x−μ)²/2σ²} with mean μ and variance σ². It is the universal limit of sums of independent variables (central limit theorem)."},
{t:"central limit theorem", f:["central limit theorem"], d:"The theorem that the sum of many independent, identically distributed variables tends to a normal distribution, regardless of the original distribution. It justifies the ubiquity of the Gaussian in measurements."},
{t:"least squares", f:["least squares","least-squares"], d:"The method of fitting a model by minimising the sum of squared residuals. For linear fits it gives closed-form parameters; with Gaussian errors it equals the maximum-likelihood estimate."},
{t:"chi-square test", f:["chi-square","chi-square test","χ²"], d:"The goodness-of-fit statistic χ² = Σ(O − E)²/E comparing observations to a model. The reduced χ² ≈ 1 indicates a good fit; much larger or smaller signals a poor model or misestimated errors."},
{t:"Newton–Raphson method", f:["Newton-Raphson","Newton–Raphson"], d:"The iterative root-finding method x_{n+1} = x_n − f(x_n)/f′(x_n), converging quadratically near a root. It is the workhorse of numerical equation solving."},
{t:"Runge–Kutta method", f:["Runge-Kutta","Runge–Kutta","RK4"], d:"A family of numerical integrators for ODEs. The fourth-order method (RK4) advances the solution with a weighted average of four slope estimates, giving O(h⁴) accuracy."},

/* ---------- ELECTRONICS & EXPERIMENTAL ---------- */
{t:"diode", f:["diode","diodes"], d:"A two-terminal device conducting current in one direction (the p-n junction's rectifying behaviour). It is the basis of rectifiers, detectors and logic; special types include Zener, tunnel, Schottky and varactor diodes."},
{t:"rectifier", f:["rectifier","rectifiers","half-wave","full-wave"], d:"A circuit converting AC to DC using diodes. Half-wave uses one diode (ripple at line frequency), full-wave (centre-tap or bridge) uses two or four (ripple at twice line frequency); a capacitor filter smooths the output."},
{t:"Zener diode", f:["Zener diode","Zener"], d:"A diode operated in reverse breakdown at a precise voltage, used for voltage regulation and references. It maintains a nearly constant voltage across a varying load."},
{t:"tunnel diode", f:["tunnel diode","Esaki diode"], d:"A heavily doped diode whose I–V curve shows a negative-resistance region from quantum tunnelling. It is used in very-high-frequency oscillators and switches."},
{t:"Schottky diode", f:["Schottky diode","Schottky"], d:"A metal–semiconductor junction diode with a low forward drop and no minority-carrier storage, making it fast. It is used in power rectification and RF detection."},
{t:"transistor", f:["transistor","transistors","BJT"], d:"A three-terminal semiconductor amplifier/switch. The bipolar junction transistor (BJT) controls a collector current I_C = β I_B from a small base current; it has common-emitter, common-base and common-collector configurations."},
{t:"emitter", f:["emitter","collector"], d:"The three terminals of a bipolar transistor: the emitter injects carriers, the thin base controls their flow, and the collector gathers them. In common-emitter operation the base is the input and the collector the output."},
{t:"current gain", f:["current gain","beta"], d:"The ratio β = I_C/I_B of collector to base current in a BJT (common-emitter). It is typically 50–300 and is the key small-signal parameter."},
{t:"FET", f:["FET","JFET","MOSFET"], d:"Field-effect transistor: a voltage-controlled device where a gate field modulates a channel's conductance. JFETs use a reverse-biased junction, MOSFETs an insulated gate; MOSFETs are the basis of modern integrated circuits."},
{t:"gate", f:["gate","drain"], d:"The terminals of a field-effect transistor: the gate controls the channel by its voltage, the source supplies carriers, and the drain collects them. The threshold voltage is the gate voltage at which the channel forms."},
{t:"threshold voltage", f:["threshold voltage"], d:"The minimum gate–source voltage at which a MOSFET's channel conducts. It is a key device parameter in digital and analog design."},
{t:"op-amp", f:["op-amp","op amp","operational amplifier"], d:"A high-gain differential amplifier with (ideally) infinite input impedance, zero output impedance and infinite gain. With negative feedback it performs precise amplification, filtering, summing and integration; the golden rules are virtual short and zero input current."},
{t:"inverting amplifier", f:["inverting amplifier","non-inverting amplifier"], d:"Basic op-amp configurations: the inverting amplifier has gain −R_f/R_in; the non-inverting has gain 1 + R_f/R_in. The inverting input is a virtual ground when feedback is active."},
{t:"feedback", f:["feedback","negative feedback"], d:"Returning part of the output to the input. Negative feedback reduces gain but improves bandwidth, linearity and stability; positive feedback is the basis of oscillators and comparators."},
{t:"gain-bandwidth product", f:["gain-bandwidth product","bandwidth"], d:"The constant product of gain and bandwidth for an op-amp. Increasing gain reduces the usable frequency range; the product equals the unity-gain frequency."},
{t:"oscillator", f:["oscillator","oscillators","Barkhausen"], d:"A circuit generating a periodic waveform from positive feedback. The Barkhausen criterion requires loop gain |Aβ| = 1 with zero (or 2πn) phase shift; common types are RC phase-shift, Wien bridge, Hartley and Colpitts."},
{t:"flip-flop", f:["flip-flop","flip-flops","latch"], d:"A bistable digital storage element. SR, D, JK and T flip-flops store one bit; the JK with J = K = 1 toggles. Flip-flops are the building blocks of registers and counters."},
{t:"counter", f:["counter","counters","register"], d:"A sequential circuit that cycles through states in a fixed order (binary ripple or synchronous counters). Registers are arrays of flip-flops storing multi-bit words."},
{t:"multiplexer", f:["multiplexer","decoder"], d:"Combinational logic: a multiplexer selects one of several inputs by select lines; a decoder activates one output line for each input code. They are basic building blocks of digital systems."},
{t:"ADC", f:["ADC","DAC","analog-to-digital","digital-to-analog"], d:"Converters between analog and digital worlds: an ADC samples a continuous signal into a digital code, a DAC reconstructs an analog voltage from a code. Resolution is set by the number of bits; the Nyquist rate bounds sampling."},
{t:"sampling theorem", f:["sampling theorem","Nyquist","Nyquist frequency"], d:"The theorem that a band-limited signal is fully determined by samples taken at more than twice its highest frequency (the Nyquist rate 2f_max). Undersampling causes aliasing."},
{t:"Boolean algebra", f:["Boolean algebra","logic gate","truth table"], d:"The algebra of binary variables with AND, OR and NOT. Logic gates (AND, OR, NOT, NAND, NOR, XOR) implement Boolean functions; NAND/NOR are universal, and truth tables enumerate behaviour."},
{t:"Karnaugh map", f:["Karnaugh map"], d:"A graphical method for minimising Boolean expressions, arranging truth-table cells so adjacent terms differ by one bit. It simplifies combinational logic into minimal sums of products."},
{t:"noise", f:["noise","signal-to-noise ratio","SNR"], d:"Random unwanted fluctuations in a measurement. The signal-to-noise ratio (SNR) quantifies quality; Johnson (thermal) noise ∝ √(4kTRB), shot noise ∝ √(2eIB) and flicker (1/f) noise are the principal types."},
{t:"Johnson noise", f:["Johnson noise","thermal noise","shot noise"], d:"Fundamental noise sources: Johnson (thermal) noise is the voltage fluctuation of a resistor at temperature T; shot noise is the statistical fluctuation of a current of discrete charges. Both set measurement limits."},
{t:"lock-in amplifier", f:["lock-in amplifier","lock-in"], d:"A phase-sensitive detector that extracts a signal at a known reference frequency, rejecting noise at all other frequencies. It is essential for measuring weak signals buried in noise."},
{t:"box-car integrator", f:["box-car integrator","boxcar"], d:"A gated integrator that averages a signal over a narrow time window synchronised to a repetitive event, improving the SNR by √N over N averages."},
{t:"transducer", f:["transducer","transducers"], d:"A device converting one form of energy into an electrical signal (thermocouple: temperature→voltage, strain gauge: strain→resistance, piezoelectric: force→charge). Sensors are transducers of physical quantities."},
{t:"thermocouple", f:["thermocouple"], d:"A temperature sensor of two dissimilar-metal junctions producing a Seebeck voltage proportional to the junction temperature difference. It is rugged and wide-ranging."},
{t:"strain gauge", f:["strain gauge"], d:"A resistive sensor whose resistance changes with mechanical strain, used in the Wheatstone bridge to measure force, pressure and deformation."},
{t:"systematic error", f:["systematic error","random error"], d:"Measurement error types: systematic errors bias all readings consistently (calibration offsets) and are removable by correction; random errors scatter readings about the mean and are reduced by averaging. Accuracy vs precision distinguish the two."},
{t:"accuracy", f:["accuracy","precision"], d:"Accuracy is closeness of a measurement to the true value; precision is the reproducibility (spread) of repeated measurements. A measurement can be precise but inaccurate (biased)."},
{t:"standard error", f:["standard error","error propagation"], d:"The uncertainty of the mean, σ/√N, from N measurements of standard deviation σ. Error propagation combines uncertainties: for Q = ab², (ΔQ/Q) = (Δa/a) + 2(Δb/b)."},
{t:"significant figures", f:["significant figures","significant figure"], d:"The digits of a measurement carrying meaning about its precision. Rules govern zeros and rounding; computed results are quoted to the least precise input."}
];
